/**
 *
 * @param name
 */
function pluralize(name: string): string {
  if (name.endsWith("y")) {
    return name.slice(0, -1) + "ies";
  }
  if (name.endsWith("s")) {
    return name + "es";
  }
  return name + "s";
}

/**
 *
 * @param entity
 * @param allEntities
 */
function getImports(entity: IEntityJson, allEntities: IEntityJson[]): string {
  const imports = new Set<string>();

  imports.add(
    "import { Entity, PrimaryGeneratedColumn, Column, BaseEntity, ManyToOne, OneToMany } from 'typeorm';",
  );

  if (entity.relationships) {
    const processedTargets = new Set<string>();
    for (const rel of entity.relationships) {
      if (processedTargets.has(rel.target)) continue;

      const targetEntity = allEntities.find((e) => e.tableName === rel.target);
      if (
        targetEntity &&
        targetEntity.namePascalCase !== entity.namePascalCase
      ) {
        imports.add(
          `import { ${targetEntity.namePascalCase} } from './${targetEntity.nameKebabCase}.entity';`,
        );
        processedTargets.add(rel.target);
      }
    }
  }

  return Array.from(imports).join("\n");
}

/**
 *
 * @param column
 */
function getColumnDecorators(column: IColumnJson): string {
  if (column.primaryKey) {
    return "@PrimaryGeneratedColumn()";
  }

  const options: string[] = [];
  if (column.typeSql) options.push(`type: '${column.typeSql}'`);
  if (column.length) options.push(`length: ${column.length}`);
  if (column.nullable) options.push("nullable: true");
  if (column.unique) options.push("unique: true");

  return `@Column({ ${options.join(", ")} })`;
}

/**
 *
 * @param relation
 * @param currentEntity
 * @param allEntities
 */
function getRelationDecorators(
  relation: IRelation,
  currentEntity: IEntityJson,
  allEntities: IEntityJson[],
): string {
  const targetEntity = allEntities.find((e) => e.tableName === relation.target);
  if (!targetEntity) {
    return `// Relation to ${relation.target} could not be resolved`;
  }

  const targetEntityPascal = targetEntity.namePascalCase;
  const targetEntityCamel = targetEntity.nameCamelCase;

  switch (relation.relationType) {
    case "ManyToOne": {
      const inversePropertyName = pluralize(currentEntity.nameCamelCase);
      return `@ManyToOne(() => ${targetEntityPascal}, ${targetEntityCamel} => ${targetEntityCamel}.${inversePropertyName})`;
    }
    case "OneToMany": {
      const inversePropertyName = currentEntity.nameCamelCase;
      return `@OneToMany(() => ${targetEntityPascal}, ${targetEntityCamel} => ${targetEntityCamel}.${inversePropertyName})`;
    }
    default:
      return "";
  }
}

/**
 *
 * @param entity
 * @param allEntities
 */
export function generateEntityFileContent(
  entity: IEntityJson,
  allEntities: IEntityJson[],
): string {
  const { namePascalCase, tableName, columns, relationships } = entity;

  const classProperties = columns
    ?.map(
      (column) =>
        `  ${getColumnDecorators(column)}\n  ${column.name}: ${column.typeTypeScript};`,
    )
    .join("\n\n");

  const processedRelations = new Set<string>();
  const relationProperties = relationships
    ?.map((rel) => {
      const key = rel.target + rel.relationType;
      if (processedRelations.has(key)) return null;
      processedRelations.add(key);

      const targetEntity = allEntities.find((e) => e.tableName === rel.target);
      if (!targetEntity) return "";

      const propertyName =
        rel.relationType === "OneToMany"
          ? pluralize(targetEntity.nameCamelCase)
          : targetEntity.nameCamelCase;
      const propertyType =
        rel.relationType === "OneToMany"
          ? `${targetEntity.namePascalCase}[]`
          : targetEntity.namePascalCase;

      return `  ${getRelationDecorators(rel, entity, allEntities)}\n  ${propertyName}: ${propertyType};`;
    })
    .filter(Boolean)
    .join("\n\n");

  return `\n${getImports(entity, allEntities)}\n\n@Entity({ name: '${tableName}' })\nexport class ${namePascalCase} extends BaseEntity {\n\n${classProperties}\n\n${relationProperties}\n\n}\n`;
}

import { IEntityJson, IRelation } from "../models/entity-json.model";

/**
 *
 * @param entity
 * @param allEntities
 */
function getInterfaceImports(
  entity: IEntityJson,
  allEntities: IEntityJson[],
): string {
  const imports = new Set<string>();

  if (entity.relationships) {
    for (const rel of entity.relationships) {
      const targetEntity = allEntities.find((e) => e.tableName === rel.target);
      if (
        targetEntity &&
        targetEntity.namePascalCase !== entity.namePascalCase
      ) {
        imports.add(
          `import { I${targetEntity.namePascalCase} } from './${targetEntity.nameKebabCase}.interface';`,
        );
      }
    }
  }

  return Array.from(imports).join("\n");
}

/**
 *
 * @param entity
 * @param allEntities
 */
export function generateInterfaceFileContent(
  entity: IEntityJson,
  allEntities: IEntityJson[],
): string {
  const { namePascalCase, columns, relationships } = entity;

  const properties = columns
    ?.map(
      (column) =>
        `  ${column.name}${column.nullable ? "?" : ""}: ${column.typeTypeScript};`,
    )
    .join("\n");

  const relationProperties = relationships
    ?.map((rel) => {
      const targetEntity = allEntities.find((e) => e.tableName === rel.target);
      if (!targetEntity) return "";

      const propertyName =
        rel.relationType === "OneToMany"
          ? `${targetEntity.nameCamelCase}s`
          : targetEntity.nameCamelCase;
      const propertyType =
        rel.relationType === "OneToMany"
          ? `I${targetEntity.namePascalCase}[]`
          : `I${targetEntity.namePascalCase}`;

      return `  ${propertyName}?: ${propertyType};`;
    })
    .join("\n");

  return `\n${getInterfaceImports(entity, allEntities)}

export interface I${namePascalCase} {
${properties}

${relationProperties}
}
`;
}

import { EMOJI } from "@constants/messages";
import { logError, logInfo } from "@utils/logger";
import { mkdirSync, readFileSync, writeFileSync } from "fs";
import { join } from "path";

import { IEntityJson } from "../models/entity-json.model";
import { generateDtoFileContent } from "./symfony-generate-dto.service";
import { generateEntityFileContent } from "./symfony-generate-entity.service";

const OUTPUT_BASE_PATH = join(process.cwd(), "dist", "generated-symfony");

/**
 *
 * @param entities
 */
export function generateSymfonyModules(entities: IEntityJson[]): void {
  if (!entities) {
    logError("No entities provided.");
    return;
  }

  logInfo(`🚀 Starting Symfony module generation...`);

  for (const entity of entities) {
    if (entity.typeEntity === "pivot") {
      logInfo(`⏩ Skipping pivot entity: ${entity.namePascalCase}`);
      continue;
    }

    const modulePath = join(OUTPUT_BASE_PATH, entity.namePascalCase);
    const dtoPath = join(modulePath, "Dto", "Request");
    const entityPath = join(modulePath, "Entity");

    mkdirSync(dtoPath, { recursive: true });
    mkdirSync(entityPath, { recursive: true });

    try {
      const entityContent = generateEntityFileContent(entity, entities);
      writeFileSync(
        join(entityPath, `${entity.namePascalCase}.php`),
        entityContent,
      );
      logInfo(`✅  Generated entity for ${entity.namePascalCase}`);

      const dtoContent = generateDtoFileContent(entity);
      writeFileSync(
        join(dtoPath, `Create${entity.namePascalCase}Dto.php`),
        dtoContent.createDto,
      );
      writeFileSync(
        join(dtoPath, `Update${entity.namePascalCase}Dto.php`),
        dtoContent.updateDto,
      );
      logInfo(`✅  Generated DTOs for ${entity.namePascalCase}`);
    } catch (error) {
      logError(
        `${EMOJI.error} Error generating files for entity ${entity.namePascalCase}: ${error}`,
      );
    }
  }

  logInfo("🎉 Symfony module generation complete!");
}

/**
 *
 * @param jsonFilePath
 */
export function generateSymfonyModulesFromFile(jsonFilePath: string): void {
  try {
    const fileContent = readFileSync(jsonFilePath, "utf-8");
    const jsonData = JSON.parse(fileContent);
    const entities: IEntityJson[] = jsonData.entities;

    if (!entities) {
      logError(`${EMOJI.error} No 'entities' array found in ${jsonFilePath}`);
      return;
    }

    generateSymfonyModules(entities);
  } catch (error) {
    logError(
      `${EMOJI.error} Failed to load or parse ${jsonFilePath}: ${error}`,
    );
    process.exit(1);
  }
}

import { IColumnJson, IEntityJson } from "../models/entity-json.model";
import { getPhpType } from "./symfony-mapping";

/**
 *
 * @param column
 */
function getValidationAssertions(column: IColumnJson): string {
  const assertions: string[] = [];
  if (!column.nullable) {
    assertions.push("new Assert\\NotBlank()");
  }

  switch (getPhpType(column.typeTypeScript)) {
    case "string":
      assertions.push('new Assert\\Type("string")');
      if (column.length) {
        assertions.push(`new Assert\\Length(max: ${column.length})`);
      }
      break;
    case "int":
      assertions.push('new Assert\\Type("integer")');
      break;
    case "float":
      assertions.push('new Assert\\Type("float")');
      break;
    case "\\DateTimeImmutable":
      assertions.push("new Assert\\Type(\\DateTimeInterface::class)");
      break;
    case "bool":
      assertions.push('new Assert\\Type("bool")');
      break;
  }

  return assertions.map((a) => `    #[${a}]`).join("\n");
}

/**
 *
 * @param entity
 */
function generateCreateDto(entity: IEntityJson): string {
  const { namePascalCase, columns } = entity;
  const properties = columns
    ?.filter((c) => !c.primaryKey && !c.foreignKey)
    .map((column) => {
      const phpType = getPhpType(column.typeTypeScript);
      const nullable = column.nullable ? "?" : "";
      return `
${getValidationAssertions(column)}
    public ${nullable}${phpType} $${column.name};
`;
    })
    .join("");

  return `<?php

namespace App\\Dto\\Request\\${namePascalCase};

use Symfony\\Component\\Validator\\Constraints as Assert;

class Create${namePascalCase}Dto
{
${properties}
}
`;
}

/**
 *
 * @param entity
 */
function generateUpdateDto(entity: IEntityJson): string {
  const { namePascalCase, columns } = entity;
  const properties = columns
    ?.filter((c) => !c.primaryKey && !c.foreignKey)
    .map((column) => {
      const phpType = getPhpType(column.typeTypeScript);
      return `
    public ?${phpType} $${column.name} = null;
`;
    })
    .join("");

  return `<?php

namespace App\\Dto\\Request\\${namePascalCase};

class Update${namePascalCase}Dto
{
${properties}
}
`;
}

/**
 *
 * @param entity
 */
export function generateDtoFileContent(entity: IEntityJson): {
  createDto: string;
  updateDto: string;
} {
  return {
    createDto: generateCreateDto(entity),
    updateDto: generateUpdateDto(entity),
  };
}

import { snakeToCamel, snakeToPascal } from "@utils/convert";

import {
  IColumnJson,
  IEntityJson,
  IRelation,
} from "../models/entity-json.model";
import { getDoctrineColumnType, getPhpType } from "./symfony-mapping";

/**
 *
 * @param entity
 */
function getEntityImports(entity: IEntityJson): string {
  const imports = new Set<string>();
  imports.add("use Doctrine\\ORM\\Mapping as ORM;");
  imports.add(`use App\\Repository\\${entity.namePascalCase}Repository;`);

  if (
    entity.relationships?.some(
      (r) => r.relationType === "OneToMany" || r.relationType === "ManyToMany",
    )
  ) {
    imports.add("use Doctrine\\Common\\Collections\\ArrayCollection;");
    imports.add("use Doctrine\\Common\\Collections\\Collection;");
  }

  return Array.from(imports).join("\n");
}

/**
 *
 * @param column
 */
function getColumnAttributes(column: IColumnJson): string {
  if (column.primaryKey) {
    return `    #[ORM\\Id]
    #[ORM\\GeneratedValue]
    #[ORM\\Column]`;
  }

  const options: string[] = [];
  const doctrineType = getDoctrineColumnType(column.typeSql);

  if (doctrineType !== "string") {
    options.push(`type: '${doctrineType}'`);
  }

  if (doctrineType === "string" && column.length) {
    options.push(`length: ${column.length}`);
  }

  if (column.nullable) {
    options.push("nullable: true");
  }
  if (column.unique) {
    options.push("unique: true");
  }

  return `    #[ORM\\Column(${options.join(", ")})]`;
}

/**
 *
 * @param relation
 * @param currentEntity
 * @param allEntities
 */
function getRelationAttributes(
  relation: IRelation,
  currentEntity: IEntityJson,
  allEntities: IEntityJson[],
): string {
  const targetEntity = allEntities.find((e) => e.tableName === relation.target);
  if (!targetEntity) return "";

  const targetEntityName = targetEntity.namePascalCase;
  const inverseSide = currentEntity.nameCamelCase;
  const owningSide = targetEntity.nameCamelCase;

  switch (relation.relationType) {
    case "ManyToOne":
      return `    #[ORM\ManyToOne(targetEntity: ${targetEntityName}::class, inversedBy: '${currentEntity.tableName}s')]`;
    case "OneToMany":
      return `    #[ORM\\OneToMany(mappedBy: '${owningSide}', targetEntity: ${targetEntityName}::class, cascade: ['persist', 'remove'])]`;
    case "OneToOne":
      return `    #[ORM\\OneToOne(inversedBy: '${inverseSide}', cascade: ['persist', 'remove'])]`;
    case "ManyToMany":
      const owning = relation.owner ? "inversedBy" : "mappedBy";
      const joinTable = relation.owner
        ? `#[ORM\\JoinTable(name: '${currentEntity.tableName}_${targetEntity.tableName}')]`
        : "";
      return `    #[ORM\\ManyToMany(targetEntity: ${targetEntityName}::class, ${owning}: '${inverseSide}s')]
    ${joinTable}`;
    default:
      return `    // Relation ${relation.relationType} not handled yet`;
  }
}

/**
 *
 * @param entity
 * @param allEntities
 */
export function generateEntityFileContent(
  entity: IEntityJson,
  allEntities: IEntityJson[],
): string {
  const { namePascalCase, tableName, columns, relationships } = entity;

  const classProperties = columns
    ?.map((column) => {
      const phpType = getPhpType(column.typeTypeScript);
      const nullable = column.nullable || column.primaryKey ? "?" : "";
      return `
${getColumnAttributes(column)}
    private ${nullable}${phpType} $${snakeToCamel(column.name)};`;
    })
    .join("\n");

  const relationProperties = relationships
    ?.map((rel) => {
      const targetEntity = allEntities.find((e) => e.tableName === rel.target);
      if (!targetEntity) return "";

      const propertyName =
        rel.relationType === "OneToMany" || rel.relationType === "ManyToMany"
          ? `${targetEntity.nameCamelCase}s`
          : targetEntity.nameCamelCase;
      const propertyType =
        rel.relationType === "OneToMany" || rel.relationType === "ManyToMany"
          ? `Collection`
          : `?${targetEntity.namePascalCase}`;

      return `
${getRelationAttributes(rel, entity, allEntities)}
    private ${propertyType} $${propertyName};`;
    })
    .join("\n");

  const constructorRelations = relationships
    ?.filter(
      (r) => r.relationType === "OneToMany" || r.relationType === "ManyToMany",
    )
    .map((rel) => {
      const targetEntity = allEntities.find((e) => e.tableName === rel.target);
      if (!targetEntity) return "";
      return `        $this->${targetEntity.nameCamelCase}s = new ArrayCollection();`;
    })
    .join("\n");

  const constructor = constructorRelations
    ? `
    public function __construct()
    {
${constructorRelations}
    }
`
    : "";

  return `<?php

namespace App\\Entity;

${getEntityImports(entity)}

#[ORM\Entity(repositoryClass: ${namePascalCase}Repository::class)]
[ORM\Table(name: '${tableName}')]
class ${namePascalCase}
{
${classProperties}
${relationProperties}
${constructor}

    // TODO: Add getters and setters
}
`;
}

import { EMOJI } from "@/assets/messages.js";
import { sqlToDoctrineType } from "@/features/scaffolders/frameworks/symfony/utils/mapping.js";
import { IAppContext } from "@/types/context.interface.js";

import {
  IColumnJson,
  IEntityJson,
  IGetEntityJson,
  IRelation,
  IRelationsEntity,
  IRelationshipJson,
} from "../models/entity-json.model.js";
import {
  Iend,
  IERDColumn,
  IERDEntity,
  IERDModel,
  IERDProject,
  IERDRelationship,
} from "../models/mdj.model.js";
import { sqlToTypeScript } from "./mapping.js";

export class ParserMDJService {
  readonly serviceName = "ParserMDJService";

  constructor(protected cli: IAppContext) {}

  init(): Promise<void> {
    return Promise.resolve();
  }
  async loadFile(path: string): Promise<string> {
    const file = await this.cli.fileSystem.readFileJson(path);
    return JSON.stringify(file, null, 2);
  }
  async parseMdjToJson(path: string): Promise<any> {
    const fileMdj = await this.loadFile(path);
    return await this.getEntities(fileMdj);
  }

  getEntities(mdjFile: string): Promise<IGetEntityJson> {
    let dictionaries!: IGetEntityJson;
    const project: IERDProject = JSON.parse(mdjFile);

    try {
      let erdModel: IERDModel | undefined;
      for (const model of project.ownedElements) {
        if (model._type === "ERDDataModel") {
          erdModel = model;
          break;
        }
      }

      if (!erdModel) {
        this.cli.logger.error(`${EMOJI.error} Aucun ERDDataModel trouvé dans le fichier MDJ.`);
        process.exit(1);
      }

      const entities: IERDEntity[] = erdModel.ownedElements;
      if (!Array.isArray(entities) || entities.length === 0) {
        this.cli.logger.error(`⏩ Pas d'entités trouvées dans ${erdModel.name}`);
        process.exit(1);
      }
      // Création du dictionnaire des entités
      dictionaries = this.createdDictionaries(entities);
      return dictionaries;
    } catch (error) {
      this.cli.logger.error(`${EMOJI.error} Erreur lors de la récupération des entités : ${error}`);
      process.exit(1);
    }
  }

  getColumns(entity: IERDEntity) {
    if (!Array.isArray(entity.columns)) {
      this.cli.logger.info(`⏩ ${entity.name} n'a pas de colonnes. Ignoré.`);
      return [];
    }

    const columnsJson: IColumnJson[] = [];

    entity.columns.forEach((column: IERDColumn) => {
      // vérifier si le type de la colonne n'est pas undifined ou null avant de l'ajouter à la relation
      if (column.type === undefined || column.type === null) {
        this.cli.logger.info(`⏩ ${column.name} n'a pas de type. Ignoré.`);
        column.type = "VARCHAR(255)";
      }
      columnsJson.push({
        id: column._id,
        name: column.name,
        typeSql: column.type.toLowerCase(),
        typeTypeScript: sqlToTypeScript(column.type),
        typeDoctrine: sqlToDoctrineType(column.type),
        parent: column._parent.$ref,
        primaryKey: Boolean(column.primaryKey),
        foreignKey: Boolean(column.foreignKey),
        length: column.length ? column.length : null,
        unique: Boolean(column.unique),
        nullable: Boolean(column.nullable),
        documentation: column.documentation,
        referenceTo: column.referenceTo ? column.referenceTo.$ref : "",
      });
    });

    return columnsJson;
  }

  createdDictionaries(entities: IERDEntity[]): IGetEntityJson {
    const dictionaryEntities: IEntityJson[] = [];
    const dictionaryEntitiesPivot: IEntityJson[] = [];
    const dictionaryEntitiesJson = new Map<string, IEntityJson>();
    const dictionaryColumns = new Map<string, IColumnJson>();
    const dictionaryRelationships = new Map<string, IRelation>();
    const dictionaryEntitiesRelationships = new Map<string, IRelationsEntity>();

    entities.forEach((entity: IERDEntity) => {
      if (!entity.name.includes("ERDDiagram")) {
        const entityJson: IEntityJson = {
          tableName: entity.name.replace("&", "_"), // code_base
          id: entity._id,
          parent: entity._parent.$ref,
          nameKebabCase: this.cli.case.toKebabCase(entity.name), // code-base
          namePascalCase: this.cli.case.toPascalCase(entity.name), // CodeBase
          nameCamelCase: this.cli.case.toCamelCase(entity.name), // codeBase
        };

        dictionaryEntitiesRelationships.set(entity.name.replace("&", "_"), {
          id: entity._id,
          relationships: [],
        });
        // Création du dictionnaire des entités
        dictionaryEntitiesJson.set(entity._id, entityJson);
      }
    });
    entities.forEach((entity: IERDEntity) => {
      if (!entity.name.includes("ERDDiagram")) {
        const relationships: IRelationshipJson[] = this.getRelationships(
          entity,
          dictionaryEntitiesJson,
        );
        relationships.forEach((relationship: IRelationshipJson) => {
          if (relationship) {
            const entSource = dictionaryEntitiesRelationships.get(relationship.source.inEntity);
            const entTarget = dictionaryEntitiesRelationships.get(relationship.target.inEntity);

            const relSource: IRelation = {
              relationName: `${relationship.source.inEntity}`,
              relationType: relationship.source.relationType,
              source: relationship.source.inEntity,
              foreignKeySource: relationship.target.columnName,
              columnNameSource: relationship.source.columnName,
              target: relationship.source.inverseSide,
              owner: false,
            };
            const relTarget: IRelation = {
              relationName: `${relationship.target.inEntity}`,
              relationType: relationship.target.relationType,
              source: relationship.target.inEntity,
              foreignKeySource: relationship.target.columnName,
              columnNameSource: relationship.source.columnName,
              target: relationship.target.inverseSide,
              owner: false,
            };

            entSource?.relationships.push(relSource);
            entTarget?.relationships.push(relTarget);
          }
        });

        // Création du dictionnaire des colonnes
        const columns: IColumnJson[] = this.getColumns(entity);
        columns.forEach((column: IColumnJson) => {
          dictionaryColumns.set(column.id, column);
        });

        const entityName = entity.name.toLowerCase().replace("&", "_");
        const entityJson: IEntityJson = {
          tableName: entityName, // code_base
          id: entity._id,
          parent: entity._parent.$ref,
          nameKebabCase: this.cli.case.toKebabCase(entityName), // code-base
          namePascalCase: this.cli.case.toPascalCase(entityName), // CodeBase
          nameCamelCase: this.cli.case.toCamelCase(entityName), // codeBase
          typeEntity: entity.name.includes("&") ? "pivot" : "entity",
          columns: columns ?? [],
          // relationships: relationships ?? [],
          relationships: dictionaryEntitiesRelationships.get(entityName)?.relationships ?? [],
        };
        dictionaryEntities.push(entityJson);
        dictionaryEntitiesJson.set(entity._id, entityJson);
      }
    });

    const json: IGetEntityJson = {
      entities: dictionaryEntities,
      "dictionary-columns": Object.fromEntries(dictionaryColumns),
      "dictionary-entities-json": Object.fromEntries(dictionaryEntitiesJson),
      "dictionary-entities-pivot": dictionaryEntitiesPivot,
      "dictionary-relationships": Object.fromEntries(dictionaryRelationships),
      "dictionary-entities-relationships": Object.fromEntries(dictionaryEntitiesRelationships),
    };

    return json;
  }

  getRelationType(source_cardinality: string, target_cardinality: string): string {
    const mapping: Record<string, string> = {
      "0..1-0..1": "OneToOne", // (optionnel)
      "1..1-1..1": "OneToOne", //(obligatoire)
      "0..*-0..1": "ManyToOne",
      "1..*-0..1": "ManyToOne", //(obligatoire)
      "0..*-1..1": "ManyToOne",
      "1..*-1..1": "ManyToOne", //(obligatoire)
      "0..1-0..*": "OneToMany",
      "1..1-0..*": "OneToMany",
      "0..*-0..*": "ManyToMany",
      "1..*-1..*": "ManyToMany",
    };
    source_cardinality ??= "1..1";
    target_cardinality ??= "1..1";

    const key = `${source_cardinality}-${target_cardinality}`;
    return mapping[key] ?? "Unknown Relation";
  }

  getInEntity(dictionaryEntitiesJson: Map<string, IEntityJson>, end: Iend): string {
    if (end.reference) {
      return dictionaryEntitiesJson.get(end.reference.$ref ?? "")?.tableName ?? "";
    }
    return "";
  }

  getRelationships(
    entity: IERDEntity,
    dictionaryEntitiesJson: Map<string, IEntityJson>,
  ): IRelationshipJson[] {
    if (!Array.isArray(entity.ownedElements)) {
      return [];
    }
    const relationshipsJson: IRelationshipJson[] = [];
    entity.ownedElements.forEach((r: IERDRelationship) => {
      const relation = {
        type: r._type,
        id: r._id,
        parent: r._parent.$ref,
        name: `${this.getInEntity(dictionaryEntitiesJson, r.end1)}--${this.getInEntity(dictionaryEntitiesJson, r.end2)}`,
        inEntity: entity.name.replace("&", "_"),

        source: {
          type: r.end1._type,
          id: r.end1._id,
          entityId: r.end1.reference.$ref,
          inEntity: this.getInEntity(dictionaryEntitiesJson, r.end1),
          columnName: r.end1.name ?? "id",
          cardinality: r.end1.cardinality ?? "1",
          parent: r.end1._parent ? r.end1._parent.$ref : "",
          relationType: this.getRelationType(r.end1.cardinality, r.end2.cardinality),
          inverseSide: this.getInEntity(dictionaryEntitiesJson, r.end2),
        },
        target: {
          type: r.end2._type,
          id: r.end2._id,
          entityId: r.end2.reference.$ref,
          inEntity: this.getInEntity(dictionaryEntitiesJson, r.end2),
          columnName: r.end2.name,
          cardinality: r.end2.cardinality ?? "1",
          parent: r.end2._parent ? r.end2._parent.$ref : "",
          relationType: this.getRelationType(r.end2.cardinality, r.end1.cardinality),
          inverseSide: this.getInEntity(dictionaryEntitiesJson, r.end1),
        },
      };

      relationshipsJson.push(relation);
    });
    return relationshipsJson;
  }
}

/**
 *
 * @param typeTypeScript
 */
export function getPhpType(typeTypeScript: string): string {
  const typeMapping: Record<string, string> = {
    string: "string",
    number: "int",
    Date: "\\DateTimeImmutable",
    boolean: "bool",
  };
  return typeMapping[typeTypeScript] || "mixed";
}

/**
 *
 * @param sqlType
 */
export function getDoctrineColumnType(sqlType: string): string {
  const lowerCaseSqlType = sqlType.toLowerCase();
  const typeMapping: Record<string, string> = {
    bigint: "bigint",
    varchar: "string",
    text: "text",
    timestamp: "datetime_immutable",
    datetime: "datetime_immutable",
    tinyint: "boolean",
    decimal: "decimal",
    int: "integer",
    float: "float",
    double: "float",
    date: "date_immutable",
    time: "time_immutable",
    boolean: "boolean",
    json: "json",
  };

  for (const key in typeMapping) {
    if (lowerCaseSqlType.includes(key)) {
      return typeMapping[key];
    }
  }
  return "string";
}

import { watch } from "chokidar";
import inquirer from "inquirer";

import { BaseCommand } from "@/commands/BaseCommand.js";
import { IProjectConfig } from "@/features/commun/projet.interface.js";
import { IProjectCommand } from "@/features/project/interfaces/project-command.interface.js";
import { FRAMEWORKS } from "@/features/scaffolders/common/config/config-frameworks.js";
import { AnyOptions } from "@/types/cli-options.type.js";
