import { IEntityJson } from "@parsersMdj/models/entity-json.model";
import { snakeToCamel } from "@utils/convert";

/**
 *
 * @param entity
 */
export function generateInterfaceService(entity: IEntityJson) {
  const properties =
    entity.columns
      ?.map((col: any) => `  ${snakeToCamel(col.name)}: ${col.typeTypeScript};`)
      .join("\n") || "";
  return `export interface I${entity.namePascalCase} {\n${properties}\n}\n`;
}

/**
 *
 * @param entity
 * @param allEntities
 */
function getInterfaceImports(
  entity: IEntityJson,
  allEntities: IEntityJson[],
): string {
  const imports = new Set<string>();

  if (entity.relationships) {
    for (const rel of entity.relationships) {
      const targetEntity = allEntities.find((e) => e.tableName === rel.target);
      if (
        targetEntity &&
        targetEntity.namePascalCase !== entity.namePascalCase
      ) {
        imports.add(
          `import { I${targetEntity.namePascalCase} } from './${targetEntity.nameKebabCase}.interface';`,
        );
      }
    }
  }

  return Array.from(imports).join("\n");
}

/**
 *
 * @param entity
 * @param allEntities
 */
export function generateInterfaceFileContent(
  entity: IEntityJson,
  allEntities: IEntityJson[],
): string {
  const { namePascalCase, columns, relationships } = entity;

  const properties = columns
    ?.map(
      (column) =>
        `  ${column.name}${column.nullable ? "?" : ""}: ${column.typeTypeScript};`,
    )
    .join("\n");

  const relationProperties = relationships
    ?.map((rel) => {
      const targetEntity = allEntities.find((e) => e.tableName === rel.target);
      if (!targetEntity) return "";

      const propertyName =
        rel.relationType === "OneToMany"
          ? `${targetEntity.nameCamelCase}s`
          : targetEntity.nameCamelCase;
      const propertyType =
        rel.relationType === "OneToMany"
          ? `I${targetEntity.namePascalCase}[]`
          : `I${targetEntity.namePascalCase}`;

      return `  ${propertyName}?: ${propertyType};`;
    })
    .join("\n");

  return `\n${getInterfaceImports(entity, allEntities)}
 
 export interface I${namePascalCase} {
 ${properties}
 
 ${relationProperties}
 }
 `;
}

import { IRoute } from "@features/frameworks/angular/model/angular-model";
import { writeFile } from "@utils/file-utils";

export const angularDefaultRouteTemplate: IRoute[] = [
  {
    path: "",
    component: "HomeComponent",
  },
];

/**
 *
 * @param rootPathProjectFramework
 * @param routes
 */
export function angularGenerateRouteService(
  rootPathProjectFramework: string,
  routes: IRoute[],
) {
  const effectiveRoutes =
    routes.length > 0 ? routes : angularDefaultRouteTemplate;

  // Génération des imports
  const imports = effectiveRoutes
    .map(
      (route: IRoute) =>
        `import { ${route.component} } from './pages/${route.component}.component';`,
    )
    .join("\n");

  // Génération du tableau de routes Angular sous forme de code TS
  const routesCode = `export const routes: Routes = [
${effectiveRoutes
  .map(
    (route: IRoute) =>
      `  { path: '${route.path}', component: ${route.component} }`,
  )
  .join(",\n")}
];`;

  const fileContent = `import { Routes } from '@angular/router';
${imports}

${routesCode}
`;

  writeFile(`${rootPathProjectFramework}/app.routes.ts`, fileContent);
}

