import {
  COMMAND_ANGULAR,
  COMMAND_ELECTRON,
  COMMAND_NESTJS,
  COMMAND_NEXTJS,
  COMMAND_NITRO,
  COMMAND_NUXT,
  COMMAND_SYMFONY,
  COMMAND_VUE,
} from "@constants/global.constants";
import { EMOJI } from "@constants/messages";
import { IFramework } from "@features/frameworks/models/framework-commun.model";
import { logError } from "@utils/logger";

/**
 * Generates the appropriate command string for creating a new framework project.
 * @param frameWork - The framework configuration object.
 * @param projectName - The name of the project to be created.
 * @returns The command string for creating the framework project.
 */
export function getCommandFramework(
  frameWork: IFramework,
  projectName: string,
) {
  const options = ``;
  if (!frameWork) {
    logError("${EMOJI.error} Framework non renseigné.");
    process.exit(1);
  }
  if (
    COMMAND_NESTJS.some((cmd) => frameWork.name.toLowerCase().includes(cmd))
  ) {
    return `nest new ${projectName} --package-manager npm ${options}`;
  }
  if (
    COMMAND_SYMFONY.some((cmd) => frameWork.name.toLowerCase().includes(cmd))
  ) {
    return `symfony new ${projectName} --version=${frameWork.version} ${frameWork.app}`;
  }
  if (
    COMMAND_ANGULAR.some((cmd) => frameWork.name.toLowerCase().includes(cmd))
  ) {
    return `ng new ${projectName} --style=scss --ssr=false --ai-config="gemini" ${options}`;
  }
  if (COMMAND_VUE.some((cmd) => frameWork.name.toLowerCase().includes(cmd))) {
    return `npx vue create ${projectName}`;
  }
  if (
    COMMAND_ELECTRON.some((cmd) => frameWork.name.toLowerCase().includes(cmd))
  ) {
    return `npx create-electron-app@latest ${projectName} ${options}`;
  }
  if (COMMAND_NUXT.some((cmd) => frameWork.name.toLowerCase().includes(cmd))) {
    return `npx nuxi init ${projectName} && cd ${projectName} && npm install`;
  }
  if (COMMAND_NITRO.some((cmd) => frameWork.name.toLowerCase().includes(cmd))) {
    return `npx giget@latest nitro ${projectName} --install `;
  }
  if (
    COMMAND_NEXTJS.some((cmd) => frameWork.name.toLowerCase().includes(cmd))
  ) {
    return `npx create-next-app ${projectName}`;
  }

  logError(`${EMOJI.error} Framework frameWork non reconnu.`);
  return `not-found`;
}

import { EMOJI } from "@constants/messages";
import { executeCommand } from "@utils/execute-command";
import * as fs from "fs";
import path from "path";

/**
 *
 * @param frameworkProjectPath
 * @param contentToAdd
 */
export function updateGitIgnore(frameworkProjectPath: string, contentToAdd: string): string {
  const gitIgnoreFile = path.join(frameworkProjectPath, ".gitignore");

  // Vérifie si le fichier .gitignore existe
  if (!fs.existsSync(gitIgnoreFile)) {
    return `Erreur: Le fichier .gitignore est introuvable dans le dossier du projet !`;
  }

  // const contentToAdd = `${ignoredFile}\n`;
  const currentContent = fs.readFileSync(gitIgnoreFile, "utf8");

  // Évite les doublons
  if (!currentContent.includes(contentToAdd)) {
    fs.appendFileSync(gitIgnoreFile, contentToAdd, "utf8");
    return `${frameworkProjectPath} : "${contentToAdd}" ajouté à .gitignore ✅`;
  }

  return `${frameworkProjectPath} : "${contentToAdd}" est déjà dans .gitignore ⚠️`;
}

/**
 *
 * @param frameworkPath
 * @param message
 */
export function gitCommit(frameworkPath: string, message: string): boolean {
  const gitCommand = `git checkout dev && git add . && git commit -m "${message}"`;
  executeCommand(
    gitCommand,
    { cwd: `${frameworkPath}`, stdio: "inherit" },
    `🚀 Création du commit ${message}`,
    `✅ Commit création avec succès !`,
    `${EMOJI.error} Erreur lors du commit !`,
  );
  return true;
}
/**
 *
 * @param message
 */
export function gitCommitAndPush(message: string): boolean {
  const gitCommand = `git add . && git commit -m "${message}" && git push`;
  executeCommand(
    gitCommand,
    { stdio: "inherit" },
    `🚀 Création du commit Initiale`,
    `✅ Commit création avec succès !`,
    `${EMOJI.error} Erreur lors du commit !`,
  );
  return true;
}
/**
 * Verifies if a directory is present in the .gitignore file.
 * @param pathGitIgnore - The path to the .gitignore file.
 * @param dir - The directory to check.
 * @returns True if the directory is found in .gitignore, false otherwise.
 */
export function verifyInGitIgnoreFile(pathGitIgnore: string, dir: string): boolean {
  if (!fs.existsSync(pathGitIgnore)) {
    // logInfo(`Le fichier .gitignore est introuvable dans le dossier du projet !`);
    return false;
  }

  const content = fs.readFileSync(pathGitIgnore, "utf8");
  const lines = content.split("\n");
  for (const line of lines) {
    if (line.trim().includes(dir)) {
      return true;
    }
  }
  return false;
}

import {
  IConfigFramework,
  IDependencies,
} from "@/features/commun/framework.interface.js";

/**
 *
 * @param framework
 * @param path
 */
export async function installTSDependencies(
  framework: IConfigFramework,
  path: string,
) {
  const dependencies: IDependencies = framework.dependencies;
  logInfo(`npm install ${dependencies}`);
  logInfo("📦 Début de l'installation des dépendances...");
  framework.dependencies.prod.forEach((dep: string) => {
    logInfo(`npm install ${dep}`);
    executeCommand(
      `npm install ${dep}`,
      { cwd: path, stdio: "inherit" },
      `📦 Installation de ${dep}`,
      `✅ Dépendances de production installées avec succès !`,
      `${EMOJI.error} Erreur lors de l'installation des dépendances de production !`,
    );
  });
  framework.dependencies.dev.forEach((dep: string) => {
    logInfo(`npm install --save-dev ${dep}`);
    executeCommand(
      `npm install --save-dev ${dep}`,
      { cwd: path, stdio: "inherit" },
      `📦 Installation de ${dep}`,
      `✅ Dépendances de production installées avec succès !`,
      `${EMOJI.error} Erreur lors de l'installation des dépendances de production !`,
    );
  });
}

/**
 * Installs Composer dependencies for PHP frameworks.
 * @param framework - The framework configuration object.
 * @param path - The installation path.
 */
export async function installComposerDependencies(
  framework: IFramework,
  path: string,
) {
  framework.dependencies.prod.forEach((dep: string) => {
    logInfo(`composer require ${dep}`);
    executeCommand(
      `composer require ${dep}`,
      { cwd: path, stdio: "inherit" },
      `📦 Installation de ${dep}`,
      `✅ Dépendances de production installées avec succès !`,
      `${EMOJI.error} Erreur lors de l'installation des dépendances de production !`,
    );
  });
  framework.dependencies.dev.forEach((dep: string) => {
    logInfo(`composer require --dev ${dep}`);
    executeCommand(
      `composer require --dev ${dep}`,
      { cwd: path, stdio: "inherit" },
      `📦 Installation de ${dep}`,
      `✅ Dépendances de production installées avec succès !`,
      `${EMOJI.error} Erreur lors de l'installation des dépendances de production !`,
    );
  });
}

