/**
 *
 * @param col
 */
export function angularFormHtmlErrorsTemplate(col: IColumnJson): string {
  const line = "\n";
  let errors = "";
  if (col.nullable === false) {
    errors += `@if (getForm['${col.name}'].errors['required']) {
            <span>Le ${col.name} est requis</span>
          }${line}`;
  }
  if (col.minLength) {
    let minLength = 0;
    if (col.minLength > 0) {
      minLength = col.minLength;
    } else {
      minLength = ANGULAR_DEFAULT_VALUES_VALIDATORS.MIN_LENGTH_STRING;
    }
    errors += `@if (getForm['${col.name}'].errors['minlength']) {
            <span>Le ${col.name} doit contenir au moins ${minLength} caractères</span>
          }${line}`;
  }
  if (col.maxlength && col.maxlength > 0) {
    let maxlength = 0;
    if (col.maxlength > 0) {
      maxlength = col.maxlength;
    } else {
      maxlength = ANGULAR_DEFAULT_VALUES_VALIDATORS.MAX_LENGTH_STRING;
    }
    errors += ` @if (getForm['${col.name}'].errors['maxlength']) {
            <span>Le ${col.name} ne peut pas dépasser ${maxlength} caractères</span>
          }${line}`;
  }
  return `
     @if (submitted && getForm['${col.name}'].errors) {
        <div class="error-message">
          ${errors}
        </div>
      }
`;
}

