/**
 *
 * @param entity
 * @param exclude
 */
export function item(
  entity: IEntityJson,
  exclude: string[],
): Record<string, any> {
  if (!entity.columns) {
    return {};
  }
  const row = entity.columns.reduce(
    (acc, column) => {
      if (!exclude.includes(column.name)) {
        acc[snakeToCamel(column.name)] = generateValue(column);
      }

      return acc;
    },
    {} as Record<string, any>,
  );

  return row;
}
