import { IColumnJson } from "@parsersMdj/models/entity-json.model";

/**
 * Génère une valeur d'exemple pour la documentation Swagger.
 * @param column
 */
export function nestjsGetExampleValue(column: IColumnJson): string {
  const tsType = column.typeTypeScript.toLowerCase();

  switch (tsType) {
    case "string":
      if (column.name.toLowerCase().includes("email"))
        return "'user@example.com'";
      if (column.name.toLowerCase().includes("name")) return "'John Doe'";
      if (column.name.toLowerCase().includes("phone")) return "'+33123456789'";
      return "'example text'";
    case "number":
      return "123";
    case "boolean":
      return "true";
    case "date":
      return "'2023-01-01T00:00:00.000Z'";
    default:
      return "null";
  }
}

import { IColumnJson } from "@parsersMdj/models/entity-json.model";

import { DtoType } from "../../../constant/nestjs-constants.constant.js";
import { nestjsGetExampleValue } from "./nest-get-example-value.service.js";

/**
 * Construit le décorateur ApiProperty pour Swagger.
 * @param column
 * @param dtoType
 */
export function nestjsBuildApiPropertyDecorator(column: IColumnJson, dtoType: DtoType): string {
  const options: string[] = [];

  if (column.description) {
    options.push(`description: '${column.description}'`);
  }

  options.push(`example: ${nestjsGetExampleValue(column)}`);

  if (column.nullable || dtoType === DtoType.UPDATE) {
    options.push("required: false");
  }

  return `@ApiProperty({ ${options.join(", ")} })`;
}

