import { IEntityJson } from "@parsersMdj/models/entity-json.model";
import { pascalToKebab, snakeToKebab } from "@utils/convert";

import { DtoType, INDENT, NEWLINE } from "../../../constant/nestjs-constants.constant.js";
import { DtoProperty } from "../../../models/nestjs-dto-property.model.js";
import { nestjsGetDtoSuffix } from "./nestjs-get-dto-suffix.service.js";

/**
 * Génère le contenu final du fichier DTO.
 * @param entity
 * @param properties
 * @param imports
 * @param dtoType
 * @param responseDtoImports
 */
export function nestjsGenerateDtoFile(
  entity: IEntityJson,
  properties: DtoProperty[],
  imports: string[],
  dtoType: DtoType,
  responseDtoImports?: Set<string>,
): string {
  const className = `${nestjsGetDtoSuffix(dtoType)}${entity.namePascalCase}Dto`;

  if (dtoType === DtoType.RESPONSE) {
    imports.push(`import { transformToISOString } from 'src/utils/date-transformer';`);
  }

  if (responseDtoImports) {
    for (const dto of responseDtoImports) {
      const kebabCaseDto = pascalToKebab(
        dto.replace("Response", "").replace("Dto", ""),
      ).toLowerCase();
      imports.push(
        `import { ${dto} } from 'src/modules/${kebabCaseDto}/dto/${pascalToKebab(dto)}.dto';`,
      );
    }
  }

  const propertiesString = properties
    .map((property) => {
      const decoratorsString = property.decorators.join(`${NEWLINE}${INDENT}`);
      const optionalMarker = property.isOptional ? "?" : "";
      return `${INDENT}${decoratorsString}${NEWLINE}${INDENT}${property.name}${optionalMarker}: ${property.tsType};`;
    })
    .join(`${NEWLINE}${NEWLINE}`);

  return `${imports.join(NEWLINE)}${NEWLINE}${NEWLINE}export class ${className} {
${propertiesString}
}
`;
}

import { IEntityJson } from "@parsersMdj/models/entity-json.model";

import { DtoType } from "../../../constant/nestjs-constants.constant.js";
import { DtoProperty } from "../../../models/nestjs-dto-property.model.js";
import { nestjsBuildDtoEntityImports } from "../../nestjs-build-imports-dto-entity.service.js";
import { nestjsGenerateDtoFile } from "./nestjs-generate-dto-file.services.js";
import { nestjsProcessColumnForDto } from "./nestjs-process-column-for-dto.service.js";
import { nestjsProcessRelationForDto } from "./nestjs-process-relation-for-dto.service.js";

/**
 *
 * @param entity
 * @param dtoType
 */
export function nestjsGenerateDto(entity: IEntityJson, dtoType: DtoType): string {
  const validationImports = new Set<string>();
  const transformImports = new Set<string>();
  const responseDtoImports = new Set<string>();
  const dtoProperties: DtoProperty[] = [];

  // Traitement des colonnes selon le type de DTO
  if (entity.columns) {
    for (const column of entity.columns) {
      const property = nestjsProcessColumnForDto(
        column,
        dtoType,
        validationImports,
        transformImports,
      );
      if (property) {
        dtoProperties.push(property);
      }
    }
  }

  // Traitement des relations (principalement pour les DTOs de réponse)
  if (dtoType === DtoType.RESPONSE && entity.relationships) {
    for (const relation of entity.relationships) {
      const property = nestjsProcessRelationForDto(
        relation,
        entity.tableName,
        validationImports,
        transformImports,
        responseDtoImports,
      );
      if (property) {
        dtoProperties.push(property);
      }
    }
  }
  // Construction des instructions d'import

  const imports = [...nestjsBuildDtoEntityImports(validationImports, transformImports)];

  // Génération du fichier DTO
  return nestjsGenerateDtoFile(entity, dtoProperties, imports, dtoType, responseDtoImports);
}

