import { IColumnJson } from "@parsersMdj/models/entity-json.model";

import { DtoType } from "../../../constant/nestjs-constants.constant.js";
import { nestjsBuildApiPropertyDecorator } from "./nestjs-build-api-property-decorator.service.js";
import { nestjsGetTransformDecorators } from "./nestjs-get-transform-decorators.service.js";
import { nestjsGetValidationDecorators } from "./nestjs-get-validation-decorators.service.js";

/**
 * Génère les décorateurs pour une colonne de DTO.
 * @param column
 * @param dtoType
 * @param validationImports
 * @param transformImports
 */
export function nestjsGetColumnDecorators(
  column: IColumnJson,
  dtoType: DtoType,
  validationImports: Set<string>,
  transformImports: Set<string>,
): string[] {
  const decorators: string[] = [];

  // ApiProperty pour Swagger
  decorators.push(nestjsBuildApiPropertyDecorator(column, dtoType));

  // Décorateurs de validation (pour Create et Update)
  if (dtoType === DtoType.CREATE || dtoType === DtoType.UPDATE) {
    decorators.push(...nestjsGetValidationDecorators(column, dtoType, validationImports));
  }

  // Décorateurs de transformation (pour Response)
  if (dtoType === DtoType.RESPONSE) {
    decorators.push(...nestjsGetTransformDecorators(column, transformImports));
  }

  return decorators;
}

import { IColumnJson } from "@parsersMdj/models/entity-json.model";

import { DtoType } from "../../../constant/nestjs-constants.constant.js";

/**
 * Détermine si une colonne est optionnelle selon le type de DTO.
 * @param column
 * @param dtoType
 */
export function nestjsGetColumnOptionalStatus(column: IColumnJson, dtoType: DtoType): boolean {
  if (dtoType === DtoType.UPDATE) {
    return true; // Tous les champs sont optionnels dans les DTOs de mise à jour
  }

  if (dtoType === DtoType.RESPONSE) {
    return column.nullable;
  }

  return column.nullable || column.primaryKey;
}

import { DtoType } from "../../../constant/nestjs-constants.constant.js";

/**
 * Retourne le suffixe approprié pour le nom de classe DTO.
 * @param dtoType
 */
export function nestjsGetDtoSuffix(dtoType: DtoType): string {
  switch (dtoType) {
    case DtoType.CREATE:
      return "Create";
    case DtoType.UPDATE:
      return "Update";
    case DtoType.RESPONSE:
      return "Response";
    default:
      return "";
  }
}

import {
  TRANSFORM_DECORATORS,
  VALIDATION_DECORATORS,
} from "../../../constant/nestjs-constants.constant.js";

/**
 * Génère les décorateurs pour une relation de DTO.
 * @param targetPascal
 * @param isArray
 * @param validationImports
 * @param transformImports
 */
export function nestjsGetRelationDecorators(
  targetPascal: string,
  isArray: boolean,
  validationImports: Set<string>,
  transformImports: Set<string>,
): string[] {
  const decorators: string[] = [];

  // ApiProperty pour Swagger
  const apiPropertyOptions = [`type: () => Response${targetPascal}Dto`];
  if (isArray) {
    apiPropertyOptions.push("isArray: true");
  }
  decorators.push(`@ApiProperty({ ${apiPropertyOptions.join(", ")}, required: false })`);

  // Décorateurs de validation et transformation
  validationImports.add(VALIDATION_DECORATORS.IS_OPTIONAL);
  transformImports.add(TRANSFORM_DECORATORS.TYPE);

  decorators.push("@IsOptional()");
  decorators.push(`@Type(() => Response${targetPascal}Dto)`);

  if (isArray) {
    validationImports.add(VALIDATION_DECORATORS.IS_ARRAY);
    validationImports.add(VALIDATION_DECORATORS.VALIDATE_NESTED);
    decorators.push("@IsArray()");
    decorators.push("@ValidateNested({ each: true })");
  } else {
    validationImports.add(VALIDATION_DECORATORS.VALIDATE_NESTED);
    decorators.push("@ValidateNested()");
  }

  return decorators;
}

