/**
 * Détermine si une colonne doit être exclue du DTO.
 * @param column
 */
export function nestjsShouldExcludeColumn(column: IColumnJson): boolean {
  const excludedColumns = ["id", "created_at", "updated_at"];
  return (
    column.primaryKey || excludedColumns.includes(column.name.toLowerCase())
  );
}

/**
 * Construit la propriété API pour Swagger.
 * @param targetPascal - Le nom de l'entité cible en PascalCase
 * @param isArray - Si la propriété est un tableau
 * @returns La propriété API formatée
 */
function nestjsBuildApiPropertyEntity(
  targetPascal: string,
  isArray: boolean,
): string {
  const options = [`type: () => ${targetPascal}`];

  if (isArray) {
    options.push("isArray: true");
  }

  return `@ApiProperty({ ${options.join(", ")} })`;
}

import { IColumnJson } from "@parsersMdj/models/entity-json.model";

import { nestjsGetTypeMappingEntity } from "./nestjs-get-type-mapping-entity-service.js";

/**
 * Construit les options de colonne pour le décorateur @Column.
 * @param column
 */
export function nestjsBuildColumnOptionsEntity(column: IColumnJson): string[] {
  const options: string[] = [];
  const typeSqlLower = column.typeSql.toLowerCase();

  // Mappage des types SQL vers les options TypeORM
  const typeMapping = nestjsGetTypeMappingEntity();

  if (typeMapping[typeSqlLower]) {
    options.push(`type: ${typeMapping[typeSqlLower]}`);
  }

  if (typeSqlLower === "varchar" && column.length) {
    options.push(`length: ${column.length}`);
  }

  if (column.nullable) {
    options.push("nullable: true");
  }

  if (column.unique) {
    options.push("unique: true");
  }

  return options;
}

