import {
  TRANSFORM_DECORATORS,
  VALIDATION_DECORATORS,
} from "../../../constant/nestjs-constants.constant.js";

/**
 * Génère les décorateurs pour une relation de DTO.
 * @param targetPascal
 * @param isArray
 * @param validationImports
 * @param transformImports
 */
export function nestjsGetRelationDecorators(
  targetPascal: string,
  isArray: boolean,
  validationImports: Set<string>,
  transformImports: Set<string>,
): string[] {
  const decorators: string[] = [];

  // ApiProperty pour Swagger
  const apiPropertyOptions = [`type: () => ${targetPascal}ResponseDto`];
  if (isArray) {
    apiPropertyOptions.push("isArray: true");
  }
  decorators.push(`@ApiProperty({ ${apiPropertyOptions.join(", ")}, required: false })`);

  // Décorateurs de validation et transformation
  validationImports.add(VALIDATION_DECORATORS.IS_OPTIONAL);
  transformImports.add(TRANSFORM_DECORATORS.TYPE);

  decorators.push("@IsOptional()");
  decorators.push(`@Type(() => ${targetPascal}ResponseDto)`);

  if (isArray) {
    validationImports.add(VALIDATION_DECORATORS.IS_ARRAY);
    validationImports.add(VALIDATION_DECORATORS.VALIDATE_NESTED);
    decorators.push("@IsArray()");
    decorators.push("@ValidateNested({ each: true })");
  } else {
    validationImports.add(VALIDATION_DECORATORS.VALIDATE_NESTED);
    decorators.push("@ValidateNested()");
  }

  return decorators;
}

import { IColumnJson } from "@parsersMdj/models/entity-json.model";

import { TRANSFORM_DECORATORS } from "../../../constant/nestjs-constants.constant.js";

/**
 * Génère les décorateurs de transformation pour les DTOs de réponse.
 * @param column
 * @param transformImports
 */
export function nestjsGetTransformDecorators(
  column: IColumnJson,
  transformImports: Set<string>,
): string[] {
  const decorators: string[] = [];

  // Exclure les champs sensibles
  if (column.name.toLowerCase().includes("password")) {
    transformImports.add(TRANSFORM_DECORATORS.EXCLUDE);
    decorators.push("@Exclude()");
    return decorators;
  }

  // Transformation pour les dates
  if (column.typeTypeScript.toLowerCase() === "date") {
    transformImports.add(TRANSFORM_DECORATORS.TRANSFORM);
    decorators.push("@Transform(transformToISOString)");
  }

  return decorators;
}

import { IColumnJson } from "@parsersMdj/models/entity-json.model";

import { VALIDATION_DECORATORS } from "../../../constant/nestjs-constants.constant.js";

/**
 * Génère les décorateurs de validation basés sur le type.
 * @param column
 * @param validationImports
 */
export function nestjsGetTypeValidationDecorators(
  column: IColumnJson,
  validationImports: Set<string>,
): string[] {
  const decorators: string[] = [];
  const tsType = column.typeTypeScript.toLowerCase();

  switch (tsType) {
    case "string":
      validationImports.add(VALIDATION_DECORATORS.IS_STRING);
      decorators.push("@IsString()");

      if (column.length) {
        validationImports.add(VALIDATION_DECORATORS.MAX_LENGTH);
        decorators.push(`@MaxLength(${column.length})`);
      }

      // Validation spéciale pour les emails
      if (column.name.toLowerCase().includes("email")) {
        validationImports.add(VALIDATION_DECORATORS.IS_EMAIL);
        decorators.push("@IsEmail()");
      }

      // Validation spéciale pour les UUIDs
      if (
        column.name.toLowerCase().includes("id") &&
        column.typeSql.toLowerCase().includes("uuid")
      ) {
        validationImports.add(VALIDATION_DECORATORS.IS_UUID);
        decorators.push("@IsUUID()");
      }
      break;

    case "number":
      validationImports.add(VALIDATION_DECORATORS.IS_NUMBER);
      decorators.push("@IsNumber()");
      break;

    case "boolean":
      validationImports.add(VALIDATION_DECORATORS.IS_BOOLEAN);
      decorators.push("@IsBoolean()");
      break;

    case "date":
      validationImports.add(VALIDATION_DECORATORS.IS_DATE);
      decorators.push("@IsDate()");
      break;

    default:
      if (tsType.includes("[]")) {
        validationImports.add(VALIDATION_DECORATORS.IS_ARRAY);
        decorators.push("@IsArray()");
      }
  }

  return decorators;
}

