/**
 * Génère les décorateurs de validation.
 * @param column
 * @param dtoType
 * @param validationImports
 */
export function nestjsGetValidationDecorators(
  column: IColumnJson,
  dtoType: DtoType,
  validationImports: Set<string>,
): string[] {
  const decorators: string[] = [];

  // Si optionnel, ajouter @IsOptional
  if (column.nullable || dtoType === DtoType.UPDATE) {
    validationImports.add(VALIDATION_DECORATORS.IS_OPTIONAL);
    decorators.push("@IsOptional()");
  }

  // Si requis, ajouter @IsNotEmpty
  if (!column.nullable && dtoType === DtoType.CREATE) {
    validationImports.add(VALIDATION_DECORATORS.IS_NOT_EMPTY);
    decorators.push("@IsNotEmpty()");
  }

  // Décorateurs basés sur le type
  decorators.push(...nestjsGetTypeValidationDecorators(column, validationImports));

  return decorators;
}

import { IColumnJson } from "@parsersMdj/models/entity-json.model";

import { DtoType } from "../../../constant/nestjs-constants.constant.js";
import { DtoProperty } from "../../../models/nestjs-dto-property.model.js";
import { nestjsGenerateColumnDescription } from "./nestjs-generate-column-description.service.js";
import { nestjsGetColumnDecorators } from "./nestjs-get-column-decorators.service.js";
import { nestjsGetColumnOptionalStatus } from "./nestjs-get-column-optional-status.service.js";
import { nestjsShouldExcludeColumn } from "./nestjs-should-exclude-column.service.js";

/**
 * Traite une colonne pour un DTO spécifique.
 * @param column
 * @param dtoType
 * @param validationImports
 * @param transformImports
 */
export function nestjsProcessColumnForDto(
  column: IColumnJson,
  dtoType: DtoType,
  validationImports: Set<string>,
  transformImports: Set<string>,
): DtoProperty | null {
  // Exclure les colonnes auto-générées des DTOs de création/mise à jour
  if (
    (dtoType === DtoType.CREATE || dtoType === DtoType.UPDATE) &&
    nestjsShouldExcludeColumn(column)
  ) {
    return null;
  }

  const decorators = nestjsGetColumnDecorators(
    column,
    dtoType,
    validationImports,
    transformImports,
  );
  const isOptional = nestjsGetColumnOptionalStatus(column, dtoType);

  return {
    name: column.name,
    isOptional,
    tsType: column.typeTypeScript,
    decorators,
    description: nestjsGenerateColumnDescription(column),
  };
}

import { IRelation } from "@parsersMdj/models/entity-json.model";
import { snakeToCamel, snakeToPascal } from "@utils/convert";

import { DtoProperty } from "../../../models/nestjs-dto-property.model.js";
import { nestjsGetRelationDecorators } from "./nestjs-get-relation-decorators.service.js";

/**
 * Traite une relation pour un DTO (principalement pour les réponses).
 * @param relation
 * @param currentEntityTableName
 * @param validationImports
 * @param transformImports
 */
export function nestjsProcessRelationForDto(
  relation: IRelation,
  currentEntityTableName: string,
  validationImports: Set<string>,
  transformImports: Set<string>,
): DtoProperty | null {
  const targetEntityTableName =
    relation.source === currentEntityTableName ? relation.target : relation.source;
  const targetPascal = snakeToPascal(targetEntityTableName);
  const targetCamel = snakeToCamel(targetEntityTableName);

  let propertyName: string;
  let propertyType: string;
  let isArray: boolean;

  // Traitement spécifique pour chaque type de relation
  switch (relation.relationType) {
    case "OneToOne":
      // Une entité a une seule relation vers une autre entité
      propertyName = targetCamel;
      propertyType = `${targetPascal}ResponseDto`;
      isArray = false;
      break;

    case "OneToMany":
      // Une entité a plusieurs relations vers d'autres entités
      propertyName = `${targetCamel}s`;
      propertyType = `${targetPascal}ResponseDto[]`;
      isArray = true;
      break;

    case "ManyToOne":
      // Plusieurs entités ont une relation vers une seule entité
      propertyName = `${targetCamel}s`;
      propertyType = `${targetPascal}ResponseDto`;
      isArray = false;
      break;

    case "ManyToMany":
      // Plusieurs entités ont des relations vers plusieurs autres entités
      propertyName = `${targetCamel}`;
      propertyType = `${targetPascal}ResponseDto[]`;
      isArray = true;
      break;

    default:
      // Type de relation non supporté
      console.warn(`Type de relation non supporté: ${relation.relationType}`);
      return null;
  }

  const decorators = nestjsGetRelationDecorators(
    targetPascal,
    isArray,
    validationImports,
    transformImports,
  );

  return {
    name: propertyName,
    isOptional: true,
    tsType: propertyType,
    decorators,
    description: `Relation ${relation.relationType} vers ${targetPascal}`,
  };
}
