/**
 *
 */
export function nestjsMainTemplate(): string {
  return `import { NestFactory } from '@nestjs/core';
  import { AppModule } from './app.module';
  import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
  import { ConfigService } from '@nestjs/config';
  import { ValidationPipe } from '@nestjs/common';
  
  async function bootstrap() {
    const app = await NestFactory.create(AppModule);
    app.useGlobalPipes(new ValidationPipe());
    
    const configService = app.get(ConfigService);
    const port = configService.get<number>('APP_PORT') || 3000;
  
    // Activation de CORS (si besoin pour un frontend Angular)
    app.enableCors({
      origin: configService.get<string>('CORS_ORIGIN') || '*',
      methods: 'GET,HEAD,PUT,PATCH,POST,DELETE',
      allowedHeaders: 'Content-Type, Authorization',
    });
  
    // Configuration de Swagger
    const swaggerConfig = new DocumentBuilder()
      .setTitle('API Documentation')
      .setDescription("Documentation de l'API NestJS")
      .setVersion('1.0')
      .addBearerAuth()
      .build();
  
    const document = SwaggerModule.createDocument(app, swaggerConfig);
    SwaggerModule.setup('api', app, document);
  
    // Démarrage du serveur
    await app.listen(port);
    logInfo(\`🚀 Application is running on: http://localhost:\${port}\`);
    logInfo(\`📜 Swagger is available at: http://localhost:\${port}/api\`);
  }
  
