}

export interface UpdateEntityData {
  name?: string;
  email?: string;
  [key: string]: any;
}

export interface GenericRepository<T extends BaseEntity> {
  findByEmail(email: string): Promise<T | null>;
  create(data: CreateEntityData): Promise<T>;
  findAll(): Promise<T[]>;
