    async delete(id: number) {
      try {
        const result = await $fetch<ApiResponse<any>>(\`\${this.apiUrl}/\${id}\`, {
          method: 'DELETE',
        })
        if (result.success) {
          this.${entity.nameCamelCase}s = this.${entity.nameCamelCase}s.filter(t => t.id !== id)
        }
