import { symfonyGetAttributeTypeORM } from "../../utils/mapping";

/**
 *
 * @param propName
 * @param type
 * @param length
 */
export function symfonyCreateAttributeORM(
  propName: string,
  type: string,
  length: string | null,
) {
  const exclude = [
    "int",
    "integer",
    "float",
    "boolean",
    "tinyint",
    "datetime",
    "dateinterval",
    "datetime_immutable",
    "array",
  ];
  let typeORM = "";

  if (!exclude.includes(type)) {
    if (["varchar", "char"].includes(type) && length) {
      typeORM = `(length: ${length})`;
    } else if (["enum"].includes(type)) {
      typeORM = `(type: Types::STRING, enumType: Status::class)`;
    } else if (["json"].includes(type)) {
      typeORM = `(type: Types::JSON)`;
    } else {
      typeORM = `(type: Types::${symfonyGetAttributeTypeORM(type)})`;
    }
  }

  return `    #[ORM\\Column${typeORM}]`;
}

import { symfonyGetAttributeTypeORM } from "../../utils/mapping";

/**
 *
 * @param propName
 * @param type
 * @param length
 */
export function symfonyCreateAttributeValidation(
  propName: string,
  type: string,
  length: string | null,
) {
  const exclude = [
    "int",
    "integer",
    "float",
    "boolean",
    "tinyint",
    "datetime",
    "dateinterval",
    "datetime_immutable",
    "array",
  ];
  const typeConstraint = "";

  if (!exclude.includes(typeConstraint)) {
    if (["varchar", "char"].includes(typeConstraint) && length) {
      type = `Length: ${length})`;
    } else if (["enum"].includes(typeConstraint)) {
      type = `(type: Types::STRING, enumType: Status::class)`;
    } else if (["json"].includes(typeConstraint)) {
      type = `(type: Types::JSON)`;
    } else {
      type = `(type: Types::${symfonyGetAttributeTypeORM(typeConstraint)})`;
    }
  }

  return `    #[Assets\\${type}]`;
}

