      );

      let propertyAccessors = symfonyGenerateRelationsService(
        snakeToCamel(col.name),
        symfonyGetPropertyType(col.typeSql),
      );

      relations.push("");
    }
      */
  });
  return [
    propertiesScalar.join("\n"),
