import { AppCommand } from "./commands/app.command.js";
import { DocCommand } from "./commands/doc.command.js";
import { GenerateCommand } from "./commands/generate.command.js";
import { McpCommand } from "./commands/mcp.command.js";
import { PluginCommand } from "./commands/plugin.command.js";
import { TreeCommand } from "./commands/tree.command.js";
import { AppContextBuilder } from "./context/context.js";
import { App } from "./core/App.js";
import { ProjectCommand } from "./features/project/commands/project.command.js";
import { FrameworkCommand } from "./features/scaffolders/common/commands/framework.command.js";
import { HandlerErrorService } from "./services/handler-error.service.js";

/**
 * Point d'entrée principal de la CLI
 *
 * Cette fonction bootstrap orchestre le démarrage complet de l'application :
 * 1. Construction du contexte avec tous les services
 * 2. Initialisation de l'application
 * 3. Enregistrement des commandes disponibles
 * 4. Lancement de l'application
 */
async function bootstrap(): Promise<void> {
  try {
    // ============================================================================
    // ÉTAPE 1 : Construction du contexte de l'application
    // ============================================================================
    // Le contexte contient tous les services (Logger, FileSystem, Generator, etc.)
    // ainsi que la configuration de l'application
    const builder = new AppContextBuilder();
    const cli = await builder.buildContext();
    cli.services.get<HandlerErrorService>("HandlerErrorService").setupGlobalHandlers();

    // 1) init services
    await cli.services.initializeAll();

    // 2) setup handlers après init
    cli.services.get<HandlerErrorService>("HandlerErrorService").setupGlobalHandlers();

    // ============================================================================
    // ÉTAPE 2 : Initialisation de l'application
    // ============================================================================
    // L'application reçoit le contexte complet et configure Commander.js
    const app = new App(cli);

    // ============================================================================
    // ÉTAPE 3 : Enregistrement des commandes disponibles
    // ============================================================================
    /**
     * Chaque commande est enregistrée auprès de l'application
     * Les commandes seront automatiquement disponibles via la CLI
     *
     * Exemples d'utilisation :
     * - mclp make service User
     * - mclp generate component Button
     * - mclp tree
     * - mclp init
     * - mclp ia "génère un service utilisateur"
     */
    app.registerCommand(McpCommand);
    app.registerCommand(DocCommand);
    app.registerCommand(AppCommand);
    app.registerCommand(TreeCommand);
    app.registerCommand(PluginCommand);
    app.registerCommand(ProjectCommand);
    app.registerCommand(GenerateCommand);
    app.registerCommand(FrameworkCommand);
    // app.registerCommand(IaCommand);

    // TODO: Automatiser l'enregistrement en scannant le dossier commands
    // Cela permettrait d'ajouter de nouvelles commandes sans modifier ce fichier

    // ============================================================================
    // ÉTAPE 4 : Lancement de l'application
    // ============================================================================
    // Parse les arguments de la ligne de commande et exécute la commande appropriée
    await app.run();
  } catch (error) {
    /**
     * Gestion d'erreur de dernier recours
     * Cette gestion s'active uniquement si le HandlerErrorService n'est pas encore prêt
     * ou si une erreur se produit avant son initialisation
     */
    console.error("❌ Erreur fatale lors du démarrage de la CLI :");
    console.error(error);
    process.exit(1);
  }
}

// ============================================================================
// Lancement du bootstrap
// ============================================================================
// Note : Utilisation de top-level await (nécessite Node.js >= 14.8 avec ESM)
await bootstrap();

import { exec } from "node:child_process";
import process from "node:process";
import { promisify } from "node:util";

const execAsync = promisify(exec);

/**
 * Vérifie si un processus MCP est déjà en cours d'exécution
 */
export async function isMcpServerRunning(): Promise<boolean> {
  try {
    if (process.platform === "win32") {
      // Windows
      const { stdout } = await execAsync('tasklist /FI "IMAGENAME eq node.exe" /FO CSV');
      return stdout.includes("mcp-server") || stdout.includes("mclp");
    } else {
      // Linux/Mac
      const { stdout } = await execAsync("ps aux | grep mcp-server | grep -v grep");
      return stdout.trim().length > 0;
    }
  } catch (error) {
    // Pas de processus trouvé
    return false;
  }
}

/**
 * Tue tous les processus MCP en cours
 */
export async function killAllMcpProcesses(): Promise<void> {
  try {
    if (process.platform === "win32") {
      // Windows - tuer les processus node.exe qui contiennent "mcp" ou "mclp"
      await execAsync('taskkill /F /FI "WINDOWTITLE eq *mcp*" /T');
      await execAsync('taskkill /F /FI "WINDOWTITLE eq *mclp*" /T');
    } else {
      // Linux/Mac
      await execAsync("pkill -f mcp-server");
      await execAsync("pkill -f mclp");
    }
    console.log("✅ Tous les processus MCP ont été arrêtés");
  } catch (error) {
    // Ignorer les erreurs si aucun processus n'est trouvé
    console.log("ℹ️ Aucun processus MCP trouvé");
  }
}

/**
 * Liste tous les processus MCP en cours
 */
export async function listMcpProcesses(): Promise<string[]> {
  try {
    if (process.platform === "win32") {
      const { stdout } = await execAsync('tasklist /FI "IMAGENAME eq node.exe" /FO CSV /V');
      const lines = stdout.split("\n");
      return lines.filter(
        (line) => line.toLowerCase().includes("mcp") || line.toLowerCase().includes("mclp"),
      );
    } else {
      const { stdout } = await execAsync("ps aux | grep -E 'mcp-server|mclp' | grep -v grep");
      return stdout
        .trim()
        .split("\n")
        .filter((line) => line.length > 0);
    }
  } catch (error) {
    return [];
  }
}

/**
 * Obtient le PID du processus MCP en cours (s'il existe)
 */
export async function getMcpPid(): Promise<number | null> {
  try {
    if (process.platform === "win32") {
      const { stdout } = await execAsync(
        "wmic process where \"commandline like '%mcp-server%'\" get processid",
      );
      const match = /\d+/.exec(stdout);
      return match ? parseInt(match[0], 10) : null;
    } else {
      const { stdout } = await execAsync("pgrep -f mcp-server");
      return stdout.trim() ? parseInt(stdout.trim().split("\n")[0], 10) : null;
    }
  } catch (error) {
    return null;
  }
}

import path from "node:path";
import { pathToFileURL } from "node:url";

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import chokidar from "chokidar";
import { z } from "zod";

import { AppContextBuilder } from "@/context/context.js";
import { AiService } from "@/services/ai.service.js";
import { PluginService } from "@/services/plugin.service.js";

import { isMcpServerRunning, killAllMcpProcesses } from "./mcp-process-utils.js";

const aiService = new AiService();
let serverInstance: McpServer | null = null;
let transportInstance: StdioServerTransport | null = null;
let isConnected = false;

// Variables pour le contexte CLI
let cliContext: any = null;
let pluginService: PluginService | null = null;

/**
 * Arrête proprement le serveur
 */
export async function stopMcpServer() {
  if (transportInstance && isConnected) {
    await transportInstance.close();
    transportInstance = null;
    serverInstance = null;
    isConnected = false;
    console.error("🛑 Serveur MCP arrêté");
  }

  // S'assurer que tous les processus sont tués
  await killAllMcpProcesses();
}

/**
 * Surveillance et chargement dynamique des plugins
 * @param server
 */
async function watchPlugins(server: McpServer) {
  const watcher = chokidar.watch(aiService.pluginsPath, {
    ignored: /(^|[\/\\])\../, // ignorer les fichiers cachés
    persistent: true,
    ignoreInitial: false, // Charger les fichiers existants au démarrage
    depth: 1, // On doit voir les manifest.json dans les sous-dossiers
  });

  const loadTool = async (filePath: string) => {
    // Cas 1: Plugin fichier unique (Legacy)
    if (filePath.endsWith(".plugin.js") && path.dirname(filePath) === aiService.pluginsPath) {
      try {
        const name = path.basename(filePath, ".plugin.js");
        const fileUrl = pathToFileURL(filePath).href;
        const module = await import(`${fileUrl}?update=${Date.now()}`);

        if (module.default) {
          // Heuristique simple: on passe le SDK si disponible, sinon aiService
          const ctx = pluginService ? pluginService.getSDKContext() : aiService;

          const definition = module.default.definition || { name, description: "Outil dynamique" };
          server.registerTool(
            definition.name,
            { description: definition.description, inputSchema: module.default.schema || {} },
            async (args: any) => {
              const result = await aiService.executeTool(definition.name, args);
              return {
                content: [{ type: "text" as const, text: JSON.stringify(result, null, 2) }],
              };
            },
          );
          console.error(`[MCP] Plugin (Legacy) chargé: ${name}`);
        }
      } catch (err) {
        console.error(`[MCP] Erreur legacy ${filePath}`, err);
      }
      return;
    }

    // Cas 2: Plugin répertoire (Manifest)
    if (path.basename(filePath) === "manifest.json") {
      try {
        const pluginDir = path.dirname(filePath);
        const manifestContent = await import(`${pathToFileURL(filePath).href}?t=${Date.now()}`, {
          with: { type: "json" },
        });

        // Validation du manifest
        const manifest = manifestContent.default;
        if (!manifest?.id || !manifest.service) {
          console.error(`[MCP] Manifest invalide pour ${filePath} (id ou service manquant)`);
          return;
        }

        const servicePath = this.cli.path.join(pluginDir, manifest.service);
        const serviceUrl = pathToFileURL(servicePath).href;

        try {
          const module = await import(`${serviceUrl}?update=${Date.now()}`);

          if (module.default) {
            // Instanciation avec injection de contexte REEL (CLI SDK)
            let context = aiService;
            if (pluginService) {
              context = pluginService.getSDKContext() as any;
            }

            const pluginInstance = new module.default(context);

            // Tentative d'enregistrement (Gérer les doublons)
            try {
              server.registerTool(
                manifest.id,
                {
                  description: manifest.description || `Plugin ${manifest.name}`,
                  inputSchema: { type: "object", properties: { project: { type: "object" } } },
                },
                async (args: any) => {
                  const result = await pluginInstance.execute(args, { project: {} });
                  return {
                    content: [{ type: "text" as const, text: JSON.stringify(result, null, 2) }],
                  };
                },
              );
              console.error(`[MCP] Plugin (Dir) chargé: ${manifest.name}`);

              // Notification désactivée pour éviter le spam/erreur JSON
              // server.sendNotification("notifications/tools/list_changed");
            } catch (regError: any) {
              if (regError.message?.includes("already registered")) {
                console.warn(`[MCP] Warning: Plugin ${manifest.id} déjà enregistré (ignoré)`);
              } else {
                throw regError;
              }
            }
          }
        } catch (importErr) {
          console.error(`[MCP] Erreur import service ${servicePath}`, importErr);
        }
      } catch (err) {
        console.error(`[MCP] Erreur loading manifest ${filePath}`, err);
      }
    }
  };

  watcher.on("add", (path) => loadTool(path)).on("change", (path) => loadTool(path));
  // .on("unlink", ...)

  console.error(`[MCP] Surveillance des plugins activée dans ${aiService.pluginsPath}`);
}

/**
 * Lancement du serveur MCP
 */
export async function runMcpServer() {
  // Initialization du contexte CLI complet
  try {
    console.error("🔄 Initialisation du contexte CLI pour MCP...");
    const builder = new AppContextBuilder();
    cliContext = await builder.buildContext();
    // On s'assure que tout est init
    pluginService = cliContext.services.get("PluginService");
    console.error("✅ Contexte CLI chargé. Service Plugin disponible.");
  } catch (error) {
    console.error("❌ Echec initialisation CLI Context:", error);
  }

  // Nettoyer les instances existantes par précaution
  if (serverInstance || transportInstance) {
    await stopMcpServer();
  }

  const server = new McpServer({
    name: "mclp-mcp-server",
    version: "1.0.0",
  });

  server.registerTool(
    "create-new-plugin",
    {
      title: "Create New Plugin",
      description: "Génère un nouveau plugin (Dossier + Manifest + Service).",
      inputSchema: {
        name: z.string().describe("Nom du plugin"),
        instruction: z.string().describe("Description de la tâche"),
      },
    },
    async ({ name, instruction }) => {
      try {
        const pluginId = await aiService.generatePlugin(instruction);
        return {
          content: [
            {
              type: "text" as const,
              text: `✅ Plugin '${pluginId}' créé avec succès (Format Dossier).`,
            },
          ],
        };
      } catch (error: unknown) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        return {
          isError: true,
          content: [{ type: "text" as const, text: `Erreur : ${errorMessage}` }],
        };
      }
    },
  );

  await watchPlugins(server);

  const transport = new StdioServerTransport();
  await server.connect(transport);

  serverInstance = server;
  transportInstance = transport;
  isConnected = true;

  console.error("🚀 MCP Server running on stdio");
}

// Lancement initial seulement si appelé directement
if (import.meta.url === `file://${process.argv[1]}`) {
  runMcpServer().catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
  });
}

/**
 * Plugin: Architect
 * Rôle: Analyse la structure du projet pour donner du contexte à l'IA.
 */
export default class ArchitectPlugin {
  // Définition statique pour que l'Hôte MCP puisse décrire l'outil à l'IA
  static definition = {
    name: "architect",
    description:
      "Analyse la structure des fichiers source et les interfaces du projet.",
    inputSchema: {
      type: "object",
      properties: {
        deepScan: { type: "boolean", description: "Scanner les sous-dossiers" },
      },
    },
  };
  // Définition MCP

  async execute(args, context) {
    context.log("args: ", args);
    context.log("context: ", context);
    context.log("Début de l'analyse structurelle du projet...");

    const projectRoot = "./src";
    const structure = {};

    try {
      // 1. Scanner les dossiers clés
      const folders = ["commands", "services", "interfaces"];

      for (const folder of folders) {
        const folderPath = `${projectRoot}/${folder}`;
        try {
          const files = await context.fs.readdir(folderPath);
          structure[folder] = files;
        } catch (e) {
          structure[folder] = "Dossier non trouvé";
        }
      }

      // 2. Lire l'interface principale pour connaître les capacités
      const interfacePath = "./src/types/ai-service.interface.ts";
      const interfaceContent = await context.fs.readFile(
        interfacePath,
        "utf-8",
      );

      // 3. Synthèse pour l'IA
      const report = {
        date: new Date().toISOString(),
        files: structure,
        capabilities: interfaceContent,
      };

      context.log("Analyse terminée. Voici ma structure actuelle :");
