import { ICaseService } from "@/types/services/case-service.interface.js";

import { BaseService } from "./base-service.service.js";

/*
Méthode	Résultat	Utilisation typique
PascalCase	MonServiceV1	Classes, Composants (React/Vue)
camelCase	monServiceV1	Variables, clés JSON
kebab-case	mon-service-v1	URLs, Classes CSS
snake_case	mon_service_v1	Bases de données (Colonnes)
slugify	mon-service-v1	URLs propres (nettoyage inclus)
*/
export class CaseService extends BaseService implements ICaseService {
  readonly serviceName = "CaseService";

  /**
   * Méthode interne pour découper n'importe quelle chaîne en tableau de mots
   * @param str - Chaine de caractères
   * @returns Tableau de mots
   */
  private getWords(str: string): string[] {
    return (
      str
        .match(/[A-Z]{2,}(?=[A-Z][a-z]+[0-9]*|\b)|[A-Z]?[a-z]+[0-9]*|[A-Z]|[0-9]+/g)
        ?.map((w) => w.toLowerCase()) ?? []
    );
  }

  // --- TRANSFORMATIONS GÉNÉRALES ---

  public toPascalCase(str: string): string {
    return this.getWords(str)
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join("");
  }

  public toCamelCase(str: string): string {
    const words = this.getWords(str);
    if (words.length === 0) return "";
    return (
      words[0] +
      words
        .slice(1)
        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
        .join("")
    );
  }

  public toKebabCase(str: string): string {
    return this.getWords(str).join("-");
  }

  public toSnakeCase(str: string): string {
    return this.getWords(str).join("_");
  }
  // --- MÉTHODES SPÉCIFIQUES (Raccourcis) ---
  public capitalize(str: string): string {
    return str.charAt(0).toUpperCase() + str.slice(1);
  }

  public slugify(str: string): string {
    return str
      .normalize("NFD") // 1. Split accents from letters
      .replace(/[\u0300-\u036f]/g, "") // 2. Strip the accent marks
      .toLowerCase()
      .trim()
      .replace(/[^\w\s-]/g, "") // 3. Remove non-word chars (except spaces/hyphens)
      .replace(/[\s_-]+/g, "-") // 4. Convert spaces/underscores to hyphens
      .replace(/^-+|-+$/g, ""); // 5. Trim hyphens from ends
  }
}

import { cosmiconfig } from "cosmiconfig";
import yaml from "js-yaml";

import { defaultconfig } from "@/config/config.js";
import { IAppConfig } from "@/types/config.interface.js";
import { IConfigService } from "@/types/services/config-service.interface.js";

import { BaseService } from "./base-service.service.js";

export class ConfigService extends BaseService implements IConfigService {
  readonly logLevel = "debug";
  private configData!: IAppConfig;
  private readonly moduleName = "mclp";
  readonly serviceName = "ConfigService";
  readonly defaults: IAppConfig = defaultconfig;

  public async load(projectPath: string = process.cwd()): Promise<IAppConfig> {
    const explorer = cosmiconfig(this.moduleName, {
      searchPlaces: [
        `.${this.moduleName}rc`,
        `.${this.moduleName}rc.json`,
        `.${this.moduleName}rc.yaml`,
        `.${this.moduleName}rc.yml`,
        `.${this.moduleName}rc.js`,
        `${this.moduleName}.config.js`,
      ],
      loaders: {
        noExt: (path, content) => yaml.load(content),
      },
    });

    try {
      const result = await explorer.search(projectPath);

      // 1. Si aucun fichier n'est trouvé, on l'initialise
      if (!result) {
        console.warn("Aucun fichier de configuration trouvé. Création du fichier par défaut.");
        return await this.initConfigFile(projectPath);
      }

      // 2. On utilise 'result.config' qui contient déjà les données parsées
      // Optionnel : fusionner avec les défauts ici
      this.configData = this.deepMerge(this.defaults, result.config) as IAppConfig;
      return this.configData;
    } catch (error) {
      console.warn(
        "Fichier de configuration corrompu ou introuvable. Utilisation des valeurs par défaut.",
      );
      this.configData = this.defaults;
      return this.configData;
    }
  }

  public async initConfigFile(projectPath: string, dataFrom?: IAppConfig): Promise<IAppConfig> {
    // On utilise le moduleName pour rester dynamique
    const fileName = `.${this.moduleName}rc.json`;
    const data = dataFrom ?? this.defaults;

    try {
      // On met à jour configData AVANT d'écrire pour que les logs suivants
      // puissent accéder à une config valide
      this.configData = data;
      console.log(`Génération du fichier de configuration : ${fileName}`);

      // let data = this.defaults;
      // if (dataFrom) {
      //   data = dataFrom;
      // }
      // On écrit le fichier proprement
      await this.cli.fileSystem.writeFile(fileName, JSON.stringify(data, null, 2));

      return this.configData;
    } catch (error) {
      console.error(
        `Impossible de créer le fichier dans ${projectPath} : ${error instanceof Error ? error.message : String(error)}`,
      );
      return this.defaults;
    }
  }

  // Accès instantané (données en mémoire)
  public get current(): IAppConfig {
    return this.configData || this.defaults;
  }
  // Pour rafraîchir manuellement quand c'est nécessaire
  public async refresh(): Promise<IAppConfig> {
    return this.load(process.cwd());
  }

  private deepMerge(target: Record<string, unknown>, source: Record<string, unknown>): unknown {
    const output = { ...target };
    if (source && typeof source === "object") {
      Object.keys(source).forEach((key) => {
        if (source[key] && typeof source[key] === "object" && !Array.isArray(source[key])) {
          output[key] = this.deepMerge(target[key] || {}, source[key]);
        } else {
          output[key] = source[key];
        }
      });
    }
    return output;
  }
}

