import * as fs from "fs";
import path from "path";

import { IGenerateOptions } from "@/commands/GenerateCommand.js";
import { IGeneratorService } from "@/types/services/generator.interface.js";

import { BaseService } from "./base-service.service.js";

export class GeneratorService extends BaseService implements IGeneratorService {
  readonly serviceName = "GeneratorService";

  private content = "";
  private fileName = "";
  private folder = "";
  private targetPath = "";

  public async newComponent(type: string, name: string, options: IGenerateOptions): Promise<void> {
    this.fileName = this.getFileName(type, name);
    this.folder = this.getTargetFolder(type);
    this.targetPath = this.cli.path.join(this.cli.rootPath, this.folder, this.fileName);

    switch (type) {
      case "service":
        this.content = this.scaffoldService(name);
        await this.save(this.targetPath, this.content, options);
        this.fileName = this.getFileName("interface", name);
        this.targetPath = `${this.getTargetFolder("interface")}/${this.fileName}`;
        this.content = this.scaffoldInterface(name);
        await this.save(this.targetPath, this.content, options);
        break;
      case "command":
        this.content = this.scaffoldCommand(name);
        await this.save(this.targetPath, this.content, options);
        break;
      case "framework":
        this.scaffoldFramework(name);
        // await this.save(this.targetPath, this.content, options);
        break;
      case "template":
        this.content = this.scaffoldTemplate(name);
        await this.save(this.targetPath, this.content, options);
        break;
    }

    if (options.dryRun) {
      this.cli.logger.info(`[DRY-RUN] Créerait le fichier : ${this.targetPath}`);
      return;
    }
  }

  private getFileName(type: string, name: string): string {
    switch (type) {
      case "service":
        return `${this.cli.case.toKebabCase(name)}.service.ts`;
      case "interface":
        return `${this.cli.case.toKebabCase(name)}-service.interface.ts`;
      case "command":
        return `${this.cli.case.toKebabCase(name)}.command.ts`;
      case "template":
        return `${this.cli.case.toKebabCase(name)}.template.ts`;
      default:
        return `${this.cli.case.toKebabCase(name)}.ts`;
    }
  }

  private getTargetFolder(type: string): string {
    switch (type) {
      case "service":
        return "src/services";
      case "interface":
        return "src/types/services";
      case "command":
        return "src/commands";
      case "template":
        return "src/templates";
      default:
        return "src";
    }
  }

  private scaffoldCommand(name: string): string {
    const className = this.cli.case.toPascalCase(name);
    const commandName = this.cli.case.toKebabCase(name);
    return `import { BaseCommand } from "./BaseCommand.js";
      import { ValidationError } from "@/errors/cli-errors.js";
      
      export class ${className}Command extends BaseCommand {
        public name = "${commandName}";
        public description = "Génère un nouvel élément de la CLI (Service, Command, Template)";
        public arguments = "<type> [names...]";
        public aliases = ["m"];
      
        public options = [
          { flags: "-f, --force", description: "Écraser les fichiers existants", defaultValue: false },
          { flags: "-d, --dry-run", description: "Simuler la création sans écrire", defaultValue: false },
        ];

        public async execute(args: string[], options: any): Promise<void> {
          const [type, ...names] = args; 
          this.logger.success("✅ ${name} Création de ${name} : Opération terminée.");
        }
      }
      `;
  }

  private scaffoldTemplate(name: string): string {
    return `import { BaseService } from "./base-service.service.js";\n\nexport class ${name}Service extends BaseService {}`;
  }

  private scaffoldService(name: string): string {
    const newName = this.cli.case.toKebabCase(name);
    const className = this.cli.case.toPascalCase(newName);
    const serviceName = `${this.cli.case.toKebabCase(newName)}-service`;
    return `import { BaseService } from "./base-service.service.js";      
import { I${className}Service } from "@/types/services/${serviceName}.interface.js";

export class ${className}Service extends BaseService implements I${className}Service {
  readonly serviceName = "${className}Service";

  public async init(): Promise<void> {
    // Implémentation par défaut vide
    // return Promise.resolve();
  }
  }
      `;
  }

  private scaffoldInterface(name: string): string {
    const className = this.cli.case.toPascalCase(name);
    return `export interface I${className}Service {
serviceName: string;
init(): Promise<void>
}`;
  }

  private scaffoldFramework(frameworkName: string) {
    const name = frameworkName.toLowerCase();
    const baseDir = this.cli.path.join(process.cwd(), "src/features/frameworks", name);

    // 1. Création de l'arborescence
    const dirs = ["services", "templates", "config", "models", "mocks", "utils"];
    dirs.forEach((dir) => fs.mkdirSync(this.cli.path.join(baseDir, dir), { recursive: true }));

    // 2. Création d'un Template d'Exemple (Hello World)
    const templatePath = this.cli.path.join(baseDir, "templates", `${name}-example.template.ts`);
    const templateContent = `
import { IEntityJson } from '../../../types';

export function ${name}ExampleTemplate(entity: IEntityJson): string {
  return \`// Fichier généré pour l'entité : \${entity.name}
export class \${entity.name} {
  constructor() {
    console.log("Hello from ${frameworkName}!");
  }
}\`;
}`;

    // 3. Création de l'Index (Le Portail) qui importe déjà l'exemple
    const indexPath = this.cli.path.join(baseDir, "services", "index.ts");
    const indexContent = `
import { IEntityJson, IProjectConfig } from '../../../types';
import { ${name}ExampleTemplate } from '../templates/${name}-example.template';

type EntityFn = (entity: IEntityJson) => string;
type ConfigFn = (config: IProjectConfig) => string;

export const ${frameworkName.charAt(0).toUpperCase() + name.slice(1)}Gen = {
  views: {
    example: ${name}ExampleTemplate as EntityFn,
  },
  data: {
    // Tes futurs templates de config ici
  }
};`;

    fs.writeFileSync(templatePath, templateContent);
    fs.writeFileSync(indexPath, indexContent);

    console.log(`
🚀 Framework "${frameworkName}" initialisé !
📂 Dossier : ${baseDir}
📝 Template créé : ${name}-example.template.ts
🔗 Index prêt : services/index.ts
  `);
  }

  private async save(
    targetPath: string,
    content: string,
    options: IGenerateOptions,
  ): Promise<void> {
    const exists = this.cli.fileSystem.exists(targetPath);
    if (exists && !options.force) {
      this.cli.logger.warn(`Le fichier ${targetPath} existe déjà. Saute.`);
      return;
    }
    await this.cli.fileSystem.writeFile(targetPath, content);
  }
}

import { IGitService } from "@/types/services/git-service.interface.js";

import { BaseService } from "./base-service.service.js";

export class GitService extends BaseService implements IGitService {
  readonly serviceName = "GitService";

  public init(): Promise<void> {
    // Si tu n'as rien à initialiser pour l'instant :
    return Promise.resolve();
  }

  async pull(): Promise<void> {
    this.cli.shell.executeSyncSpawn("git", ["pull"], "inherit", true);
    return Promise.resolve();
  }

  async push(): Promise<void> {
    this.cli.shell.executeSyncSpawn("git", ["push"], "inherit", true);
    return Promise.resolve();
  }

  async commit(message: string): Promise<void> {
    this.cli.shell.executeSyncSpawn("git", ["commit -m", message], "inherit", true);
    return Promise.resolve();
  }

  async add(folder = "."): Promise<void> {
    this.cli.shell.executeSyncSpawn("git", ["add", folder], "inherit", true);
    return Promise.resolve();
  }

  async addToGitignore(path: string, contentToAdd: string): Promise<string> {
    const gitIgnorePath = this.cli.path.join(path, ".gitignore");

    await this.cli.fileSystem.ensureFile(gitIgnorePath);

    const currentContent = await this.cli.fileSystem.readFile(gitIgnorePath);

    const isAlreadyPresent = this.verifyInGitIgnoreFile(currentContent, contentToAdd);

    if (isAlreadyPresent) {
      throw new Error(`${path} : "${contentToAdd}" est déjà présent ⚠️`);
    }
    const entry = currentContent.endsWith("\n") ? `${contentToAdd}\n` : `\n${contentToAdd}\n`;

    await this.cli.fileSystem.appendFile(gitIgnorePath, entry);

    return `${path} : "${contentToAdd}" ajouté à .gitignore ✅`;
  }
  async removeInGitignore(path: string, itemsToRemove: string[]): Promise<string> {
    const gitIgnorePath = this.cli.path.join(path, ".gitignore");

    if (!this.cli.fileSystem.exists(gitIgnorePath)) {
      return "Aucun fichier .gitignore trouvé, rien à supprimer.";
    }

    const currentContent = await this.cli.fileSystem.readFile(gitIgnorePath);
    const lines = currentContent.split("\n");

    // On filtre pour ne garder que les lignes qui ne sont pas dans notre liste à supprimer
    const filteredLines = lines.filter(
      (line) => !itemsToRemove.some((item) => line.trim() === item.trim()),
    );

    if (lines.length === filteredLines.length) {
      return "Aucun changement nécessaire dans .gitignore.";
    }

    await this.cli.fileSystem.writeFile(gitIgnorePath, filteredLines.join("\n"));
    return `Éléments retirés de .gitignore dans ${path} ✅`;
  }

  async gitAddAndCommitAndPush(folder: string, message: string): Promise<boolean> {
    try {
      await this.add(folder);
      await this.commit(message);
      await this.push();
      this.cli.logger.info("Changements poussés avec succès !");
      return true;
    } catch (error) {
      this.cli.errorHandler.handle(error, "Échec de l'opération Git");
      return false;
    }
  }
  /**
   * Vérifie si le contenu à ajouter est déjas dans .gitignore.
   * @param content - Contenu du fichier .gitignore.
   * @param currentContent
   * @param item - Contenu à ajouter.
   * @returns Retourne le nouveau contenu du fichier .gitignore ou un tableau vide.
   */
  private verifyInGitIgnoreFile(currentContent: string, item: string): boolean {
    if (!item.trim()) return false; // Ne pas valider si l'item est vide
    return currentContent.split("\n").some((line) => line.trim() === item.trim());
  }
}

import { CliError } from "@/errors/cli-errors.js";
import { IAppContext } from "@/types/context.interface.js";
import { IHandlerErrorService } from "@/types/services/error-handler.interface.js";

import { BaseService } from "./base-service.service.js";

export class HandlerErrorService extends BaseService implements IHandlerErrorService {
  readonly serviceName = "HandlerErrorService";

  constructor(cli: IAppContext) {
    super(cli);
  }

  /**
   * Configure les écouteurs globaux pour Node.js.
   * Empêche la CLI de crash sans loguer l'erreur.
   */
  public setupGlobalHandlers(): void {
    process.on("uncaughtException", (error: Error) => {
      this.handle(error, "Uncaught Exception");
    });

    process.on("unhandledRejection", (reason: unknown) => {
      this.handle(
        reason instanceof Error ? reason : new Error(String(reason)),
        "Unhandled Rejection",
      );
    });
  }

  /**
   * Méthode centrale pour traiter toute erreur de l'application.
   * Cette méthode est ultra-sécurisée et ne devrait jamais planter.
   * @param error - erreur à traiter
   * @param contextMessage - message contextuel optionnel
   */
  public handle(error: unknown, contextMessage?: string): void {
    try {
      // 1️⃣ Normaliser unknown → Error
      const err: Error =
        error instanceof Error
          ? error
          : new Error(typeof error === "string" ? error : JSON.stringify(error));

      const isCliError = err instanceof CliError;
      const message = isCliError ? err.message : `An unexpected error occurred: ${err.message}`;
      const exitCode = isCliError ? err.exitCode : 1;

      // 2️⃣ Logger SAFE avec protection totale
      this.safeLogError(contextMessage, message);

      // 3️⃣ Stack trace en debug uniquement (ultra safe)
      this.safeLogStackTrace(err);

      // 4️⃣ Sortie propre
      process.exit(exitCode);
    } catch (handlerError) {
      // Si même le handler d'erreur plante, on utilise console brut
      console.error("❌ Critical error in error handler:");
      console.error("Context:", contextMessage ?? "Unknown");
      console.error("Original error:", error);
      console.error("Handler error:", handlerError);
      process.exit(1);
    }
  }

  /**
   * Log une erreur de manière sécurisée avec plusieurs fallbacks.
   * Cette méthode ne devrait jamais planter.
   * @param contextMessage - contexte de l'erreur
   * @param message - message d'erreur
   */
  private safeLogError(contextMessage: string | undefined, message: string): void {
    try {
      const logger = this.cli?.logger;

      // Tentative d'utilisation du logger configuré
      if (logger && typeof logger.error === "function") {
        const finalMessage = contextMessage ? `${contextMessage}: ${message}` : message;
        logger.error(finalMessage);
        return;
      }
    } catch (loggerError) {
      // Le logger a planté, on affiche un warning et on continue vers le fallback
      console.error("⚠️  Logger failed, falling back to console:", loggerError);
    }

    // Fallback : utilisation de console.error
    const finalMessage = contextMessage ? `${contextMessage}: ${message}` : message;
    console.error("❌", finalMessage);
  }

  /**
   * Affiche la stack trace seulement en mode debug.
   * Cette méthode ne plante jamais, même si la récupération du log level échoue.
   * @param err - erreur dont on veut afficher la stack
   */
  private safeLogStackTrace(err: Error): void {
    try {
      const logLevel = this.getLogLevel();

      if (logLevel === "debug" && err.stack) {
        console.error("\n📍 Stack trace:");
        console.error(err.stack);
      }
    } catch (stackError) {
      // Si la récupération du log level plante, on affiche quand même la stack
      // en cas d'erreur critique (mieux vaut trop d'info que pas assez)
      if (err.stack) {
        console.error("\n⚠️  Stack trace (log level check failed):");
        console.error(err.stack);
      }
    }
  }

  /**
   * Récupère le log level de manière ultra-sécurisée avec plusieurs fallbacks.
   * Cette méthode ne plante jamais.
   * @returns le log level ou undefined si impossible à déterminer
   */
  private getLogLevel(): string | undefined {
    try {
      // Méthode 1 : Via this.cli.config.logLevel (standard)
      try {
        if (this.cli.config.logLevel) {
          return this.cli.config.logLevel;
        }
      } catch {
        this.cli.logger.warn("⚠️  Failed to get log level from this.cli.config.logLevel");
      }

      // Méthode 2 : Via une variable d'environnement
      // Priorité 2 : Env (Sûr aussi)
      if (process.env.LOG_LEVEL) return process.env.LOG_LEVEL;

      // Méthode 3 : Via les arguments de ligne de commande
      if (process.argv.includes("--debug") || process.argv.includes("-d")) {
        return "debug";
      }

      if (process.argv.includes("--verbose") || process.argv.includes("-v")) {
        return "verbose";
      }

      // Valeur par défaut
      return "info";
    } catch {
      // En cas d'erreur dans la récupération, on retourne undefined
      return "debug";
    }
  }

  /**
   * Méthode utilitaire pour forcer l'affichage de détails en mode debug.
   * Utile pour le développement.
   * @param title - titre de la section de debug
   * @param data - données à afficher
   */
  public debugLog(title: string, data: unknown): void {
    try {
      const logLevel = this.getLogLevel();

      if (logLevel === "debug") {
        console.log(`\n🔍 ${title}:`);
        console.log(JSON.stringify(data, null, 2));
      }
    } catch {
      // En cas d'erreur, on ignore silencieusement
    }
  }

  /**
   * Vérifie si le service est correctement initialisé.
   * Utile pour le debugging.
   * @returns true si le service est correctement configuré
   */
  public isProperlyConfigured(): boolean {
    try {
      return !!(this.cli?.logger && typeof this.cli.logger.error === "function");
    } catch {
      return false;
    }
  }

  /**
   * Retourne un diagnostic de l'état du service.
   * Utile pour comprendre pourquoi les erreurs ne sont pas loguées correctement.
   * @returns objet contenant les informations de diagnostic
   */
  public getDiagnostics(): {
    hasCliContext: boolean;
    hasLogger: boolean;
    hasConfig: boolean;
    logLevel: string | undefined;
    isFullyConfigured: boolean;
  } {
    try {
      return {
        hasCliContext: !!this.cli,
        hasLogger: !!this.cli?.logger,
        hasConfig: !!this.cli?.config,
        logLevel: this.getLogLevel(),
        isFullyConfigured: this.isProperlyConfigured(),
      };
    } catch {
      return {
        hasCliContext: false,
        hasLogger: false,
        hasConfig: false,
        logLevel: undefined,
        isFullyConfigured: false,
      };
    }
  }
}

import chalk from "chalk";

import { ILoggerService } from "@/types/services/logger-service.interface.js";

import { BaseService } from "./base-service.service.js";

export class LoggerService extends BaseService implements ILoggerService {
  readonly serviceName = "LoggerService";
  init(): Promise<void> {
    return Promise.resolve();
  }
  info(message: string, meta?: object): void {
    console.log(
      chalk.blue("ℹ"),
      message,
      meta ? chalk.gray(JSON.stringify(meta)) : "",
    );
  }

  success(message: string): void {
    console.log(chalk.green("✔"), chalk.bold(message));
  }

  warn(message: string, meta?: object): void {
    console.warn(chalk.yellow("⚠"), chalk.yellow(message), meta || "");
  }

  error(message: string, error?: Error): void {
    console.error(chalk.red("✖"), chalk.red.bold(message));
    if (error && this.config.logLevel === "debug") {
      console.error(chalk.gray(error.stack));
    }
  }

  debug(message: string, meta?: object): void {
    if (this.config.logLevel === "debug") {
      console.log(chalk.magenta("⚙ [DEBUG]"), message, meta || "");
    }
  }
}

import path from "path";

import { IPathService } from "@/types/services/path-service.interface.js";

import { BaseService } from "./base-service.service.js";

export class PathService extends BaseService implements IPathService {
  readonly serviceName = "PathService";

  public init(): Promise<void> {
    return Promise.resolve();
  }

  /**
   * Joint plusieurs segments en un seul chemin propre.
   * @param segments - Les segments de chemin à joint
   * @returns Le chemin joint
   */
  public join(...segments: string[]): string {
    this.validateSegments(segments);
    // Log de debug interne (optionnel)
    // console.debug(`[PathService] Joined: ${segments.join(' + ')} => ${result}`);
    return path.join(...segments);
  }

  /**
   * Résout une séquence de chemins en un chemin absolu.
   * @param segments - Les segments de chemin à resilier
   * @returns Le chemin absolu
   */
  public resolve(...segments: string[]): string {
    return path.resolve(...segments);
  }

  /**
   * Retourne le chemin relatif d'un point A vers un point B.
   * @param from - Point A
   * @param to - Point B
   * @returns Chemin relatif
   */
  public getRelativePath(from: string, to: string): string {
    return path.relative(from, to);
  }

  /**
   * Retourne l'extension du fichier (ex: .jpg, .json).
   * @param filePath - Chemin du fichier
   * @returns L'extension
   */
  public getExtension(filePath: string): string {
    return path.extname(filePath);
  }

  /**
   * Retourne le nom du fichier.
   * @param filePath - Chemin du fichier
   * @param withExtension - Si faux, retourne juste le nom sans l'extension.
   * @returns Le nom du fichier
   */
  public getFileName(filePath: string, withExtension = true): string {
    return withExtension
      ? path.basename(filePath)
      : path.basename(filePath, path.extname(filePath));
  }

  /**
   * Retourne le nom du répertoire parent.
   * @param filePath - Chemin du fichier
   * @returns Le nom du répertoire
   */
  public getDirectory(filePath: string): string {
    return path.dirname(filePath);
  }

  /**
   * Nettoie les erreurs de format (doubles slashs, etc.).
   * @param filePath - Chemin à nettoyer
   * @returns Chemin normalisé
   */
  public normalize(filePath: string): string {
    return path.normalize(filePath);
  }

  /**
   * Vérifie si un chemin est absolu.
   * @param filePath - Chemin à vérifier
   * @returns `true` si le chemin est absolu, `false` sinon
   */
  public isAbsolute(filePath: string): boolean {
    return path.isAbsolute(filePath);
  }
  /**
   * Vérifie que le chemin n'est pas vide.
   * @param filePath - Chemin à vérifier
   * @param paramName - Nom du paramètre pour le message d'erreur. Par exemple, `filePath` ou `dirPath`.
   */
  public validatePath(filePath: string, paramName: string): void {
    if (!filePath || filePath.trim() === "") {
      throw new Error(`${paramName} cannot be empty`);
    }
  }
  /**
   * Méthode privée pour valider les entrées et éviter les crashs.
   * @param segments - Les segments de chemin à resilier
   */
  private validateSegments(segments: string[]): void {
    if (segments.some((s) => typeof s !== "string")) {
      throw new Error(
        "[PathService] Tous les segments du chemin doivent être des chaînes de caractères.",
      );
    }
  }
  /**
   * Retourne un objet dont les propriétés représentent des éléments significatifs du chemin.
   * (root, dir, base, ext, name)
   * @param filePath - Chemin à analyser
   * @returns Objet contenant les éléments significatifs
   */
  public parse(filePath: string): path.ParsedPath {
    this.validatePath(filePath, "filePath");
    return path.parse(filePath);
  }

  /**
   * Retourne une chaîne de chemin à partir d'un objet (l'inverse de parse).
   * @param pathObject - Objet contenant les éléments significatifs
   * @returns Chemin
   */
  public format(pathObject: path.FormatInputPathObject): string {
    return path.format(pathObject);
  }

  /**
   * Retourne l'équivalent spécifique au système (utile pour Windows long paths \\?\).
   * @param filePath - Chemin
   * @returns Chemin
   */
  public toNamespacedPath(filePath: string): string {
    return path.toNamespacedPath(filePath);
  }

  /**
   * Retourne le séparateur de segment spécifique au système (\ ou /).
   * @returns Le séparateur
   */
  public getSeparator(): string {
    return path.sep;
  }

  /**
   * Retourne le délimiteur de chemin spécifique au système (; ou :).
   * @returns Le délimiteur
   */
  public getDelimiter(): string {
    return path.delimiter;
  }

  /**
   * Sécurité : Vérifie si un chemin (child) est réellement à l'intérieur d'un autre (parent).
   * Très utile pour empêcher les accès non autorisés (ex: ../../etc/passwd).
   * @param parent - Chemin parent
   * @param child - Chemin enfant
   * @returns `true` si le chemin enfant est à l'intérieur du chemin parent, `false` sinon
   */
  public isChildOf(parent: string, child: string): boolean {
    const relative = path.relative(parent, child);
    return relative.length > 0 && !relative.startsWith("..") && !path.isAbsolute(relative);
  }

  /**
   * Nettoie un chemin des caractères potentiellement dangereux.
   * @param filePath - Chemin à nettoyer
   * @returns Chemin nettoy
   */
  public sanitize(filePath: string): string {
    // Remplace les multiples slashes et normalise
    return filePath.replace(/[<>:"|?*]/g, "").trim();
  }
}

import { ISDKContext } from "@/types/commun/sdk-context.interface.js";
import { IPlugin, IPluginManifest } from "@/types/plugin.interface.js";
import { IPluginService } from "@/types/services/plugin-service.interface.js";

import { BaseService } from "./base-service.service.js";

export class PluginService extends BaseService implements IPluginService {
  readonly serviceName = "PluginService";

  private pluginsBaseDir = this.cli.path.join(process.cwd(), "plugins");
  private pluginsIndex = this.cli.path.join(this.pluginsBaseDir, "index.json");
  private pluginsIndexJson!: any;
  private pluginsManifest!: IPluginManifest;
  private plugin!: IPlugin;

  public override async init(): Promise<void> {
    return Promise.resolve();
  }

  /**
   * Charge et exécute un plugin dynamiquement
   * @param pluginId
   * @param type
   */
  async load(pluginId: string, type: string): Promise<any> {
    const indexPluginJson = await this.cli.fileSystem.readFile(this.pluginsIndex);
    this.pluginsIndexJson = JSON.parse(indexPluginJson);
    const typePlugin = this.pluginsIndexJson.plugins[type];
    this.plugin = typePlugin.find((p: any) => p.id === pluginId);

    if (!this.plugin) {
      throw new Error(`Plugin ${pluginId} non trouvé dans la catégorie ${type}`);
    }
    this.plugin.pluginDir = this.cli.path.join(this.pluginsBaseDir, this.plugin.pluginDir);
    const manifestPath = this.cli.path.join(this.plugin.pluginDir, "manifest.json");

    if (!this.cli.fileSystem.exists(manifestPath)) {
      throw new Error(`le fichier manifest.json du plugin ${pluginId}.json n'existe pas`);
    }

    const manifestJson = await this.cli.fileSystem.readFile(manifestPath);
    this.pluginsManifest = JSON.parse(manifestJson);

    const isComplet = await this.verifyPlugin(this.pluginsManifest);

    if (!isComplet) {
      throw new Error(`Le plugin ${pluginId} n'est pas complet`);
    }

    const sdk: ISDKContext = this.getSDKContext();
    const service = this.cli.path.join(this.plugin.pluginDir, this.pluginsManifest.service);
    const module = await import(`file://${service}`);
    const PluginClass = module.default;
    if (!PluginClass) {
      throw new Error(`Le plugin ${pluginId} n'a pas d'exportation par défaut (export default).`);
    }

    const instance = new PluginClass(sdk);
    return {
      instance,
      manifest: this.pluginsManifest,
      pluginDir: this.plugin.pluginDir,
    };
  }

  /**
   * Liste tous les plugins installés physiquement dans le dossier /plugins
   * @returns Liste des plugins
   */
  async list(): Promise<any[]> {
    if (!this.cli.fileSystem.exists(this.pluginsBaseDir)) {
      return [];
    }

    const folders = await this.cli.fileSystem.readDir(this.pluginsBaseDir);
    const availablePlugins = [];

    for (const folder of folders) {
      const manifestPath = this.cli.path.join(this.pluginsBaseDir, folder, "manifest.json");

      if (this.cli.fileSystem.exists(manifestPath)) {
        const content = await this.cli.fileSystem.readFile(manifestPath);
        availablePlugins.push(JSON.parse(content));
      }
    }

    return availablePlugins;
  }

  async listByType(type: string): Promise<any[]> {
    const plugins = await this.list();
    return plugins.filter((p: any) => p.type === type);
  }

  async verifyPlugin(manifest: any): Promise<boolean> {
    const errors: string[] = [];
    let propertiesManifest: string[] = [];
    const pathPlugin = {
      templateDir: "",
      service: "",
    };
    console.log(manifest);
    if (this.plugin.type === "scaffolder") {
      propertiesManifest = ["id", "name", "templateDir", "service", "blueprints"];
      pathPlugin.templateDir = this.cli.path.join(this.plugin.pluginDir, manifest.templateDir);
    } else if (this.plugin.type === "tool") {
      propertiesManifest = ["id", "name", "service"];
    }
    pathPlugin.service = this.cli.path.join(this.plugin.pluginDir, manifest.service);

    for (const property of propertiesManifest) {
      if (!manifest[property]) {
        errors.push(
          `Le plugin manifest.json du plugin ${manifest.id} n'a pas de propriété ${property}`,
        );
      }
    }
    if (errors.length > 0) {
      throw new Error(errors.join("\n"));
    }

    if (!this.cli.fileSystem.exists(pathPlugin.service) && pathPlugin.service) {
      throw new Error(`Le fichier d'entrée du plugin ${manifest.id}.service.js n'existe pas`);
    }

    if (pathPlugin.templateDir && this.plugin.type === "scaffolder") {
      if (!this.cli.fileSystem.exists(pathPlugin.templateDir)) {
        throw new Error(`Le dossier de templates du plugin ${manifest.id} n'existe pas`);
      }
    }

    if (manifest.blueprints) {
      for (const blueprint of manifest.blueprints) {
        const blueprintPath = this.cli.path.join(pathPlugin.templateDir, blueprint.template);
        if (!this.cli.fileSystem.exists(blueprintPath)) {
          errors.push(`Le template ${blueprint.template} du plugin ${manifest.id} n'existe pas`);
        }
      }
    }

    if (errors.length > 0) {
      throw new Error(errors.join("\n"));
    }
    return true;
  }

  getSDKContext(): ISDKContext {
    return {
      log: {
        info: (msg: string) => this.cli.logger.info(msg),
        success: (msg: string) => this.cli.logger.success(msg),
        error: (msg: string) => this.cli.logger.error(msg),
        warning: (msg: string) => this.cli.logger.warn(msg),
        debug: (msg: string) => this.cli.logger.debug(msg),
      },
      fs: {
        writeAsync: (p, c) => this.cli.fileSystem.writeFile(p, c),
        exists: (p) => this.cli.fileSystem.exists(p),
        readFile: (p, e) => this.cli.fileSystem.readFile(p),
      },
      render: (pluginDir: string, tplDir: string, tpl: string, data: any) =>
        this.cli.template.render(pluginDir, tplDir, tpl, data),
      config: this.cli.config as any,
    };
  }
}

import inquirer from "inquirer";

import { IPromptService } from "@/types/services/prompt-service.interface.js";

import { BaseService } from "./base-service.service.js";

export class PromptService extends BaseService implements IPromptService {
  readonly serviceName = "PromptService";

  /**
   * Pose une question simple (texte)
   * @param message
   * @param name
   */
  async askText(message: string, name = "value"): Promise<string> {
    const result = await inquirer.prompt([
      {
        type: "input",
        name: name,
        message: message,
      },
    ]);
    return result[name];
  }

  /**
   * Propose un choix dans une liste
   * @param message
   * @param choices
   */
  async askChoiceList<T>(message: string, choices: string[]): Promise<T> {
    const name = "selection";
    const result = await inquirer.prompt([
      {
        type: "list",
        name: name,
        message: message,
        choices: choices,
      },
    ]);
    return result[name];
  }
  /**
   * Propose un choix dans une liste
   * @param message
   * @param choices
   */
  async askChoiceCheckbox<T>(message: string, choices: string[]): Promise<T> {
    const name = "selection";
    const result = await inquirer.prompt([
      {
        type: "checkbox",
        name: name,
        message: message,
        choices: choices,
      },
    ]);
    return result[name];
  }

